14	`include "VX_cache_define.vh"
15	
16	module VX_cache import VX_gpu_pkg::*; #(
17	    parameter `STRING INSTANCE_ID   = "",
18	
19	    parameter NUM_REQS              = 4,      // Number of Word requests per cycle
20	
21	    parameter MEM_PORTS             = 1,      // Number of memory ports
22	
23	    parameter CACHE_SIZE            = 32768,  // Size of cache in bytes
24	    parameter LINE_SIZE             = 64,     // Size of line inside a bank in bytes
25	    parameter NUM_BANKS             = 4,      // Number of banks
26	    parameter NUM_WAYS              = 4,      // Number of associative ways
27	    parameter WORD_SIZE             = 16,     // Size of a word in bytes
28	    parameter SECTOR_SIZE           = LINE_SIZE, // Size of a sector in bytes (fill/eviction/mem-request granule); = LINE_SIZE => 1 sector
29	
30	    parameter CRSQ_SIZE             = 0,      // Core Response Queue Size
31	    parameter MSHR_SIZE             = 16,     // Miss Reserv Queue Knob
32	    parameter MRSQ_SIZE             = 4,      // Memory Response Queue Size
33	    parameter MREQ_SIZE             = 0,      // Memory Request Queue Size (0 = derived minimum)
34	
35	    parameter LATENCY               = 2,      // Bank pipeline depth (2 = classic lookup+commit; larger defers the data array)
36	
37	    parameter WRITE_ENABLE          = 1,      // Enable cache writeable
38	
39	    parameter WRITEBACK             = 0,      // Enable cache writeback
40	
41	    parameter DIRTY_BYTES           = 0,      // Enable dirty bytes on writeback
42	
43	    parameter REPL_POLICY           = `CS_REPL_FIFO, // Replacement policy
44	
45	    parameter TAG_WIDTH             = UUID_WIDTH + 1, // core request tag size
46	
47	    parameter CORE_OUT_BUF          = 3,      // core response output buffer (bank-level buffering derived internally)
48	    parameter MEM_OUT_BUF           = 3,
49	
50	    parameter IS_LLC                = 0,      // last-level cache: banks own AMO commit + RVA reservation tracking
51	
52	    parameter AMO_ENABLE            = 0       // synthesize atomic-op logic in the banks
53	 ) (
54	`ifdef PERF_ENABLE
55	    output cache_perf_t     cache_perf,
56	`endif
57	    input wire clk,
58	    input wire reset,
59	    VX_mem_bus_if.slave     core_bus_if [NUM_REQS],
60	    VX_mem_bus_if.master    mem_bus_if [MEM_PORTS]
61	);
62	    `STATIC_ASSERT(NUM_BANKS == (1 << `CLOG2(NUM_BANKS)), ("invalid parameter: number of banks must be power of 2"))
63	    `STATIC_ASSERT(WRITE_ENABLE || !WRITEBACK, ("invalid parameter: writeback requires write enable"))
64	    `STATIC_ASSERT(WRITEBACK || !DIRTY_BYTES, ("invalid parameter: dirty bytes require writeback"))
65	    `STATIC_ASSERT(NUM_BANKS >= MEM_PORTS, ("invalid parameter: number of banks must be greater or equal to number of memory ports"))
66	    localparam REQ_SEL_WIDTH   = `UP(`CS_REQ_SEL_BITS);
67	    localparam WORD_SEL_WIDTH  = `UP(`CS_WORD_SEL_BITS);
68	    localparam MSHR_ADDR_WIDTH = `LOG2UP(MSHR_SIZE);
69	    localparam MEM_TAG_WIDTH   = `CACHE_MEM_TAG_WIDTH(MSHR_SIZE, NUM_BANKS, MEM_PORTS, UUID_WIDTH);
70	    localparam WORDS_PER_LINE  = LINE_SIZE / WORD_SIZE;
71	    localparam WORD_WIDTH      = WORD_SIZE * 8;
72	    localparam WORD_SEL_BITS   = `CLOG2(WORDS_PER_LINE);
73	    localparam BANK_SEL_BITS   = `CLOG2(NUM_BANKS);
74	    localparam BANK_SEL_WIDTH  = `UP(BANK_SEL_BITS);
75	    localparam LINE_ADDR_WIDTH = (`CS_WORD_ADDR_WIDTH - BANK_SEL_BITS - WORD_SEL_BITS);
76	    localparam CORE_REQ_DATAW  = LINE_ADDR_WIDTH + 1 + WORD_SEL_WIDTH + WORD_SIZE + WORD_WIDTH + TAG_WIDTH + `UP(MEM_ATTR_WIDTH);
77	    localparam CORE_RSP_DATAW  = WORD_WIDTH + TAG_WIDTH;
78	    localparam BANK_MEM_TAG_WIDTH = UUID_WIDTH + MSHR_ADDR_WIDTH;
79	    localparam MEM_REQ_DATAW   = (`CS_LINE_SECTOR_ADDR_WIDTH + 1 + SECTOR_SIZE + `CS_SECTOR_WIDTH + BANK_MEM_TAG_WIDTH + `UP(MEM_ATTR_WIDTH));
80	    localparam MEM_RSP_DATAW   = `CS_SECTOR_WIDTH + MEM_TAG_WIDTH;
81	    localparam MEM_PORTS_SEL_BITS = `CLOG2(MEM_PORTS);
82	    localparam MEM_PORTS_SEL_WIDTH = `UP(MEM_PORTS_SEL_BITS);
83	    localparam MEM_ARB_SEL_BITS = `CLOG2(`CDIV(NUM_BANKS, MEM_PORTS));
84	    localparam REQ_XBAR_BUF    = (NUM_REQS > 2) ? 2 : 0;
85	    localparam CORE_RSP_BUF_ENABLE = (NUM_BANKS != 1) || (NUM_REQS != 1);
86	    localparam MEM_REQ_BUF_ENABLE = (NUM_BANKS != 1);
87	`ifdef PERF_ENABLE
88	    wire [NUM_BANKS-1:0] perf_read_miss_per_bank;
89	    wire [NUM_BANKS-1:0] perf_write_miss_per_bank;
90	    wire [NUM_BANKS-1:0] perf_evictions_per_bank;
91	    wire [NUM_BANKS-1:0] perf_mshr_stall_per_bank;
92	`endif
93	    VX_mem_bus_if #(
94	        .DATA_SIZE (WORD_SIZE),
95	        .TAG_WIDTH (TAG_WIDTH)
96	    ) core_bus2_if[NUM_REQS]();
97	    wire [NUM_BANKS-1:0] per_bank_flush_begin;
98	    wire [`UP(UUID_WIDTH)-1:0] flush_uuid;
99	    wire [NUM_BANKS-1:0] per_bank_flush_end;
100	    wire [NUM_BANKS-1:0] per_bank_core_req_fire;
101	    VX_cache_init #(
102	        .NUM_REQS  (NUM_REQS),
103	        .NUM_BANKS (NUM_BANKS),
104	        .TAG_WIDTH (TAG_WIDTH),
105	        .BANK_SEL_LATENCY (`TO_OUT_BUF_REG(REQ_XBAR_BUF)) // request xbar latency
106	    ) cache_init (
107	        .clk             (clk),
108	        .reset           (reset),
109	        .core_bus_in_if  (core_bus_if),
110	        .core_bus_out_if (core_bus2_if),
111	        .bank_req_fire   (per_bank_core_req_fire),
112	        .flush_begin     (per_bank_flush_begin),
113	        .flush_uuid      (flush_uuid),
114	        .flush_end       (per_bank_flush_end)
115	    );
116	    VX_mem_bus_if #(
117	        .DATA_SIZE (SECTOR_SIZE),
118	        .TAG_WIDTH (MEM_TAG_WIDTH)
119	    ) mem_bus_tmp_if[MEM_PORTS]();
120	    wire [MEM_PORTS-1:0]                    mem_rsp_queue_valid;
121	    wire [MEM_PORTS-1:0][MEM_RSP_DATAW-1:0] mem_rsp_queue_data;
122	    wire [MEM_PORTS-1:0]                    mem_rsp_queue_ready;
123	    for (genvar i = 0; i < MEM_PORTS; ++i) begin : g_mem_rsp_queue
124	        VX_elastic_buffer #(
125	            .DATAW   (MEM_RSP_DATAW),
126	            .SIZE    (MRSQ_SIZE),
127	            .OUT_REG (MRSQ_SIZE > 2)
128	        ) mem_rsp_queue (
129	            .clk        (clk),
130	            .reset      (reset),
131	            .valid_in   (mem_bus_tmp_if[i].rsp_valid),
132	            .data_in    (mem_bus_tmp_if[i].rsp_data),
133	            .ready_in   (mem_bus_tmp_if[i].rsp_ready),
134	            .valid_out  (mem_rsp_queue_valid[i]),
135	            .data_out   (mem_rsp_queue_data[i]),
136	            .ready_out  (mem_rsp_queue_ready[i])
137	        );
138	    end
139	    wire [MEM_PORTS-1:0][MEM_RSP_DATAW-MEM_ARB_SEL_BITS-1:0] mem_rsp_queue_data_s;
