503	    wire [NUM_REQS-1:0]  perf_core_reads_per_req;
504	    wire [NUM_REQS-1:0]  perf_core_writes_per_req;
505	    wire [NUM_REQS-1:0]  perf_crsp_stall_per_req;
506	    wire [MEM_PORTS-1:0] perf_mem_stall_per_port;
507	    `BUFFER(perf_core_reads_per_req, core_req_valid & core_req_ready & ~core_req_rw);
508	    `BUFFER(perf_core_writes_per_req, core_req_valid & core_req_ready & core_req_rw);
509	    for (genvar i = 0; i < NUM_REQS; ++i) begin : g_perf_crsp_stall_per_req
510	        assign perf_crsp_stall_per_req[i] = core_bus_if[i].rsp_valid && ~core_bus_if[i].rsp_ready;
511	    end
512	    for (genvar i = 0; i < MEM_PORTS; ++i) begin : g_perf_mem_stall_per_port
513	        assign perf_mem_stall_per_port[i] = mem_bus_if[i].req_valid && ~mem_bus_if[i].req_ready;
514	    end
515	    wire [`CLOG2(NUM_REQS+1)-1:0]  perf_core_reads_per_cycle;
516	    wire [`CLOG2(NUM_REQS+1)-1:0]  perf_core_writes_per_cycle;
517	    wire [`CLOG2(NUM_REQS+1)-1:0]  perf_crsp_stall_per_cycle;
518	    wire [`CLOG2(NUM_BANKS+1)-1:0] perf_read_miss_per_cycle;
519	    wire [`CLOG2(NUM_BANKS+1)-1:0] perf_write_miss_per_cycle;
520	    wire [`CLOG2(NUM_BANKS+1)-1:0] perf_evictions_per_cycle;
521	    wire [`CLOG2(NUM_BANKS+1)-1:0] perf_mshr_stall_per_cycle;
522	    wire [`CLOG2(MEM_PORTS+1)-1:0] perf_mem_stall_per_cycle;
523	    `POP_COUNT(perf_core_reads_per_cycle, perf_core_reads_per_req);
524	    `POP_COUNT(perf_core_writes_per_cycle, perf_core_writes_per_req);
525	    `POP_COUNT(perf_read_miss_per_cycle, perf_read_miss_per_bank);
526	    `POP_COUNT(perf_write_miss_per_cycle, perf_write_miss_per_bank);
527	    `POP_COUNT(perf_evictions_per_cycle, perf_evictions_per_bank);
528	    `POP_COUNT(perf_mshr_stall_per_cycle, perf_mshr_stall_per_bank);
529	    `POP_COUNT(perf_crsp_stall_per_cycle, perf_crsp_stall_per_req);
530	    `POP_COUNT(perf_mem_stall_per_cycle, perf_mem_stall_per_port);
531	    reg [PERF_CTR_BITS-1:0] perf_core_reads;
532	    reg [PERF_CTR_BITS-1:0] perf_core_writes;
533	    reg [PERF_CTR_BITS-1:0] perf_read_misses;
534	    reg [PERF_CTR_BITS-1:0] perf_write_misses;
535	    reg [PERF_CTR_BITS-1:0] perf_evictions;
536	    reg [PERF_CTR_BITS-1:0] perf_mshr_stalls;
537	    reg [PERF_CTR_BITS-1:0] perf_mem_stalls;
538	    reg [PERF_CTR_BITS-1:0] perf_crsp_stalls;
539	    always @(posedge clk) begin
540	        if (reset) begin
541	            perf_core_reads   <= '0;
542	            perf_core_writes  <= '0;
543	            perf_read_misses  <= '0;
544	            perf_write_misses <= '0;
545	            perf_evictions    <= '0;
546	            perf_mshr_stalls  <= '0;
547	            perf_mem_stalls   <= '0;
548	            perf_crsp_stalls  <= '0;
549	        end else begin
550	            perf_core_reads   <= perf_core_reads   + PERF_CTR_BITS'(perf_core_reads_per_cycle);
551	            perf_core_writes  <= perf_core_writes  + PERF_CTR_BITS'(perf_core_writes_per_cycle);
552	            perf_read_misses  <= perf_read_misses  + PERF_CTR_BITS'(perf_read_miss_per_cycle);
553	            perf_write_misses <= perf_write_misses + PERF_CTR_BITS'(perf_write_miss_per_cycle);
554	            perf_evictions    <= perf_evictions    + PERF_CTR_BITS'(perf_evictions_per_cycle);
555	            perf_mshr_stalls  <= perf_mshr_stalls  + PERF_CTR_BITS'(perf_mshr_stall_per_cycle);
556	            perf_mem_stalls   <= perf_mem_stalls   + PERF_CTR_BITS'(perf_mem_stall_per_cycle);
557	            perf_crsp_stalls  <= perf_crsp_stalls  + PERF_CTR_BITS'(perf_crsp_stall_per_cycle);
558	        end
559	    end
560	    assign cache_perf.reads        = perf_core_reads;
561	    assign cache_perf.writes       = perf_core_writes;
562	    assign cache_perf.read_misses  = perf_read_misses;
563	    assign cache_perf.write_misses = perf_write_misses;
564	    assign cache_perf.evictions    = perf_evictions;
565	    assign cache_perf.bank_stalls  = perf_collisions;
566	    assign cache_perf.mshr_stalls  = perf_mshr_stalls;
567	    assign cache_perf.mem_stalls   = perf_mem_stalls;
568	    assign cache_perf.crsp_stalls  = perf_crsp_stalls;
569	`endif
570	endmodule
