52	  params_t(const Cache::Config &config) {
53	    int32_t offset_bits = config.L - config.W;
54	    int32_t index_bits = config.C - (config.L + config.A + config.B);
55	    assert(offset_bits >= 0);
56	    assert(index_bits >= 0);
57	
58	    this->log2_num_inputs = log2ceil(config.num_inputs);
59	
60	    int32_t sector_bits = config.L - config.S; // sectors per line = 2^sector_bits
61	    assert(sector_bits >= 0);
62	
63	    this->sets_per_bank = 1 << index_bits;
64	    this->lines_per_set = 1 << config.A;
65	    this->words_per_line = 1 << offset_bits;
66	    this->sectors_per_line = 1 << sector_bits;
67	
68	    // Sector select: high part of the in-line offset, bits [S .. L-1].
69	    this->sector_select_addr_start = config.S;
70	    this->sector_select_addr_end = (config.S + sector_bits - 1);
71	
72	    // Word select
73	    this->word_select_addr_start = config.W;
74	    this->word_select_addr_end = (this->word_select_addr_start + offset_bits - 1);
75	
76	    // Bank select
77	    this->bank_select_addr_start = (1 + this->word_select_addr_end);
78	    this->bank_select_addr_end = (this->bank_select_addr_start + config.B - 1);
79	
80	    // Set select
81	    this->set_select_addr_start = (1 + this->bank_select_addr_end);
82	    this->set_select_addr_end = (this->set_select_addr_start + index_bits - 1);
83	
84	    // Tag select
85	    this->tag_select_addr_start = (1 + this->set_select_addr_end);
86	    this->tag_select_addr_end = (config.addr_width - 1);
