138	// One sector of a line: the fill / eviction / mem-request granule (= mem_block).
139	struct sector_t {
140	  bool valid;
141	  bool dirty;
142	  uint64_t dirty_mask;                 // per-byte dirty bits; the writeback byte-enable
143	  std::shared_ptr<mem_block_t> data;  // sector bytes (= one mem_block)
