153	struct line_t {
154	  uint64_t tag;
155	  uint32_t lru_ctr;
156	  std::vector<sector_t> sectors;       // sectors_per_line (1 when no sectoring)
157	
158	  bool any_valid() const {
159	    for (const auto &s : sectors) if (s.valid) return true;
160	    return false;
161	  }
