172	static inline void sector_merge(sector_t& sec, const std::shared_ptr<mem_block_t>& src, uint64_t byteen) {
173	  // Copy-on-write only when shared. sec.data may be aliased with in-flight
174	  // responses, fill payloads, or writeback messages; mutating in place would
175	  // corrupt them. When this sector is the sole owner, mutate in place to
176	  // avoid a heap allocation on the hot path.
177	  if (sec.data) {
178	    if (sec.data.use_count() > 1) {
179	      sec.data = make_mem_block_copy(*sec.data);
180	    }
181	  } else {
182	    sec.data = make_mem_block();
183	    std::memset(sec.data->data(), 0, sec.data->size());
184	  }
185	  if (src) {
186	    for (uint32_t b = 0; b < VX_CFG_MEM_BLOCK_SIZE; ++b) {
187	      if (byteen & (1ull << b)) {
188	        (*sec.data)[b] = (*src)[b];
189	      }
190	    }
191	  }
192	}
