194	struct set_t {
195	  std::vector<line_t> lines;
196	  uint32_t fifo_ptr;    // next victim for FIFO policy
197	
198	  set_t(uint32_t num_ways, uint32_t sectors_per_line)
199	      : lines(num_ways), fifo_ptr(0) {
200	    for (auto &line : lines)
201	      line.sectors.resize(sectors_per_line);
202	  }
203	
204	  void reset() {
205	    for (auto &line : lines) {
206	      line.reset();
207	    }
208	    fifo_ptr = 0;
209	  }
210	
211	  // Pure tag lookup: returns the line-resident way (tag match with any sector
212	  // valid) or -1; fills free/repl line ids. No mutation. The caller derives a
213	  // sector hit by checking the requested sector's valid bit on the returned way.
214	  // Callers must invoke update_lru() *after* all stall checks pass, otherwise
215	  // PLRU counters drift on retry.
216	  int tag_match(uint64_t tag, uint8_t policy, uint32_t rand_idx,
217	                int *free_line_id, int *repl_line_id) const {
218	    int hit_line_id = -1;
219	    *free_line_id = -1;
220	    *repl_line_id = 0;
221	
222	    uint32_t max_cnt = 0;
223	    bool has_valid = false;
224	    bool plru_chosen = false;
225	
226	    for (uint32_t i = 0, n = lines.size(); i < n; ++i) {
227	      const auto &line = lines.at(i);
228	
229	      if (!line.any_valid()) {
230	        if (*free_line_id == -1)
231	          *free_line_id = i;
232	        continue;
233	      }
234	      has_valid = true;
235	
236	      if (line.tag == tag)
237	        hit_line_id = i;
238	
239	      if (policy == Cache::PLRU) {
240	        if (!plru_chosen || line.lru_ctr >= max_cnt) {
241	          max_cnt = line.lru_ctr;
242	          *repl_line_id = i;
243	          plru_chosen = true;
244	        }
245	      }
246	    }
247	
248	    // Select victim per policy (for miss path).
249	    switch (policy) {
250	    case Cache::FIFO:
251	      *repl_line_id = fifo_ptr % lines.size();
252	      break;
253	    case Cache::RANDOM:
254	      *repl_line_id = rand_idx % lines.size();
255	      break;
256	    case Cache::PLRU:
257	    default:
258	      if (!has_valid)
259	        *repl_line_id = (*free_line_id != -1) ? *free_line_id : 0;
260	      break;
261	    }
262	
263	    return hit_line_id;
264	  }
265	
266	  // Apply PLRU age update for a tag access. Pass hit_line_id == -1 for a miss
267	  // (all valid lines age, no reset). Call once per *committed* access.
268	  void update_lru(int hit_line_id) {
269	    for (uint32_t i = 0, n = lines.size(); i < n; ++i) {
270	      auto &line = lines.at(i);
271	      if (!line.any_valid())
272	        continue;
273	      if ((int)i == hit_line_id) {
274	        line.lru_ctr = 0;
275	      } else {
276	        ++line.lru_ctr;
277	      }
278	    }
279	  }
280	
281	  // Choose a victim line for installing a fill. Does NOT mutate state.
282	  int select_victim(uint8_t policy, uint32_t rand_idx,
283	                    int *free_line_id, int *repl_line_id) const {
284	    *free_line_id = -1;
285	    *repl_line_id = 0;
286	
287	    uint32_t max_cnt = 0;
288	    bool has_valid = false;
289	
290	    for (uint32_t i = 0, n = lines.size(); i < n; ++i) {
291	      const auto &line = lines.at(i);
292	      if (!line.any_valid()) {
293	        if (*free_line_id == -1)
294	          *free_line_id = i;
295	        continue;
296	      }
297	      has_valid = true;
298	      if (policy == Cache::PLRU) {
299	        if (line.lru_ctr >= max_cnt) {
300	          max_cnt = line.lru_ctr;
301	          *repl_line_id = i;
302	        }
303	      }
304	    }
305	
306	    switch (policy) {
307	    case Cache::FIFO:
308	      *repl_line_id = fifo_ptr % lines.size();
309	      break;
310	    case Cache::RANDOM:
311	      *repl_line_id = rand_idx % lines.size();
312	      break;
313	    case Cache::PLRU:
314	    default:
315	      if (!has_valid)
316	        *repl_line_id = (*free_line_id != -1) ? *free_line_id : 0;
317	      break;
318	    }
319	
320	    return (*free_line_id != -1) ? *free_line_id : *repl_line_id;
321	  }
322	
323	  // Find the way currently resident for `tag` (any sector valid), or -1.
324	  int find_resident(uint64_t tag) const {
325	    for (uint32_t i = 0, n = lines.size(); i < n; ++i) {
326	      if (lines.at(i).any_valid() && lines.at(i).tag == tag)
327	        return (int)i;
328	    }
329	    return -1;
330	  }
331	};
332	
333	struct bank_req_t {
334	
335	  using Ptr = std::shared_ptr<bank_req_t>;
336	
337	  enum ReqType {
338	    None = 0,
339	    Fill = 1,
340	    Replay = 2,
341	    Core = 3,
342	    AmoProbe = 4  // non-LLC AMO passthrough: probe-and-invalidate then forward
343	  };
344	
345	  uint64_t addr;
346	  uint32_t hart_id;
347	  uint64_t req_tag;
348	  uint64_t uuid;
349	  uint32_t mshr_id;
350	  ReqType type;
351	  bool write;
352	  MemOp op;           // AMO state (op/width/rhs/hart_id) is derived from
353	                      // this + byteen + data + hart_id without a sideband.
354	  // For write-through write-misses that piggy-back on a pending fill MSHR:
355	  // the core response was already sent at miss time, so Replay must not
356	  // emit another response — only run sector_merge.
357	  bool skip_core_rsp;
358	
359	  // TLM data:
360	  //   For Core writes: incoming write data + byteen.
361	  //   For Fill: captured fill data from below (mem_rsp.data).
362	  std::shared_ptr<mem_block_t> data;
363	  uint64_t byteen;
364	
365	  // `flags.amo_unsigned` distinguishes signed vs unsigned MIN/MAX.
366	  // Other bits ride along for future use.
367	  MemFlags flags;
368	
369	  // Bank admission order, stamped once in processInputs. MSHR replay drains
370	  // by this stamp, so chain order is admission order regardless of whether a
371	  // request joins the chain at admission or later at pipe exit (a request
372	  // still riding the pipe must not be ordered behind a younger request that
373	  // coalesced at admission).
374	  uint64_t adm_seq;
375	
376	  // AMO state. memop_is_atomic(op) classifies the request; the LSU
377	  // packs rs2 into data at byte_off, so the cache extracts rhs via
378	  // amo_load_word and width via byteen popcount.
379	
380	  bank_req_t() {
381	    this->reset();
382	  }
383	
384	  void reset() {
385	    addr = 0;
386	    hart_id = 0;
387	    req_tag = 0;
388	    uuid = 0;
389	    mshr_id = 0;
390	    type = ReqType::None;
391	    write = false;
392	    op = MemOp::LD;
393	    skip_core_rsp = false;
394	    data.reset();
395	    byteen = 0;
396	    flags = MemFlags{};
397	    adm_seq = 0;
398	  }
399	
400	  friend std::ostream &operator<<(std::ostream &os, const bank_req_t &req) {
401	    os << "addr=0x" << std::hex << req.addr;
402	    os << ", rw=" << std::dec << req.write;
403	    os << ", type=" << req.type;
404	    os << ", req_tag=" << req.req_tag;
405	    os << ", hart_id=" << req.hart_id;
406	    os << " (#" << req.uuid << ")";
407	    return os;
408	  }
409	};
