411	struct mshr_entry_t {
412	  bank_req_t bank_req;
413	  uint32_t set_id;
414	  uint64_t addr_tag;
415	  uint32_t sector_id;   // coalescing/fill granule: a miss is per-(set,tag,sector)
416	  uint32_t line_id;
417	  uint64_t seq;         // enqueue order; replays drain oldest-first to preserve
418	                        // program order among coalesced same-line accesses.
419	
420	  mshr_entry_t() {
421	    this->reset();
422	  }
423	
424	  void reset() {
425	    bank_req.reset();
426	    set_id = 0;
427	    addr_tag = 0;
428	    sector_id = 0;
429	    line_id = 0;
430	    seq = 0;
431	  }
