433	
434	class MSHR {
435	public:
436	  MSHR(uint32_t size)
437	      : entries_(size), ready_reqs_(0), size_(0) {}
438	
439	  uint32_t capacity() const {
440	    return entries_.size();
441	  }
442	
443	  uint32_t size() const {
444	    return size_;
445	  }
446	
447	  bool empty() const {
448	    return (0 == size_);
449	  }
450	
451	  bool full() const {
452	    assert(size_ <= entries_.size());
453	    return (size_ == entries_.size());
454	  }
455	
456	  bool has_ready_reqs() const {
457	    return (ready_reqs_ != 0);
458	  }
459	
460	  const mshr_entry_t &peek(uint32_t id) const {
461	    return entries_.at(id);
462	  }
463	
464	  // Returns true if there is an active pending request for the given
465	  // set/tag/sector. Coalescing is per-sector: a fill installs one sector, so
466	  // only same-sector misses share it (different-sector misses to the same line
467	  // each get their own fill). If true, optionally returns the root entry id.
468	  bool lookup(uint32_t set_id, uint64_t addr_tag, uint32_t sector_id, uint32_t *root_id = nullptr) const {
469	    for (uint32_t i = 0, n = entries_.size(); i < n; ++i) {
470	      const auto &entry = entries_.at(i);
471	      if (entry.bank_req.type != bank_req_t::None && entry.set_id == set_id && entry.addr_tag == addr_tag && entry.sector_id == sector_id) {
472	        if (root_id)
473	          *root_id = i;
474	        return true;
475	      }
476	    }
477	    return false;
478	  }
479	
480	  // True if any matching entry OTHER than exclude_id is still Core-typed,
481	  // i.e. the chain's fill hasn't run replay() over it yet. Distinguishes a
482	  // fill-pending chain (a plain enqueue will be marked by the fill) from a
483	  // draining chain (a new entry must be marked ready via defer_to_replay).
484	  bool has_pending_fill(uint32_t set_id, uint64_t addr_tag, uint32_t sector_id, int exclude_id) const {
485	    for (int i = 0, n = (int)entries_.size(); i < n; ++i) {
486	      if (i == exclude_id) {
487	        continue;
488	      }
489	      const auto &entry = entries_.at(i);
490	      if (entry.bank_req.type == bank_req_t::Core && entry.set_id == set_id && entry.addr_tag == addr_tag && entry.sector_id == sector_id) {
491	        return true;
492	      }
493	    }
494	    return false;
495	  }
496	
497	  // Enqueue a new core request and return the allocated entry id.
498	  int enqueue(const bank_req_t &bank_req, uint32_t set_id, uint64_t addr_tag, uint32_t sector_id) {
499	    assert(bank_req.type == bank_req_t::Core);
500	    for (uint32_t i = 0, n = entries_.size(); i < n; ++i) {
501	      auto &entry = entries_.at(i);
502	      if (entry.bank_req.type == bank_req_t::None) {
503	        entry.bank_req = bank_req;
504	        entry.set_id = set_id;
505	        entry.addr_tag = addr_tag;
506	        entry.sector_id = sector_id;
507	        entry.line_id = 0; // victim is selected at Fill time
508	        entry.seq = bank_req.adm_seq;
509	        ++size_;
510	        return i;
511	      }
512	    }
513	    std::abort(); // no free slot found!
514	    return -1;
515	  }
516	
517	  // Mark all pending requests matching the entry's (set,tag,sector) for replay.
518	  mshr_entry_t &replay(uint32_t id) {
519	    auto &root_entry = entries_.at(id);
520	    assert(root_entry.bank_req.type == bank_req_t::Core);
521	    // A prior fill's replay batch may still be draining: a stalled fill
522	    // (writeback egress backpressure) can sit in the pipe while a second
523	    // fill is admitted behind it, so two fills' replays can be live at once.
524	    // This is safe — the MSHR coalesces misses, so the two fills are for
525	    // distinct lines and this replay marks only its own line's waiters; the
526	    // accumulated ready_reqs_ stays correct and dequeue drains oldest-first, so
527	    // each line's waiters still replay in program order. Double-replaying the
528	    // same fill is caught by the Core-type assert above.
529	    for (auto &entry : entries_) {
530	      if (entry.bank_req.type == bank_req_t::Core && entry.set_id == root_entry.set_id && entry.addr_tag == root_entry.addr_tag && entry.sector_id == root_entry.sector_id) {
531	        entry.bank_req.type = bank_req_t::Replay;
532	        ++ready_reqs_;
533	      }
534	    }
535	    return root_entry;
536	  }
537	
538	  // Convert a just-enqueued entry into a ready Replay. Used when a request
539	  // targets a line whose same-(set,tag,sector) chain is already draining:
540	  // nothing will mark the new entry, so it joins the replay stream itself
541	  // and seq order keeps it behind the older chained accesses.
542	  void defer_to_replay(uint32_t id) {
543	    auto &entry = entries_.at(id);
544	    assert(entry.bank_req.type == bank_req_t::Core);
545	    entry.bank_req.type = bank_req_t::Replay;
546	    ++ready_reqs_;
547	  }
548	
549	  // Peek the entry dequeue() would return next (oldest ready replay), or
550	  // nullptr. Lets the fill-forward drain inspect the chain head without
551	  // consuming it.
552	  const mshr_entry_t* peek_next_replay() const {
553	    const mshr_entry_t *picked = nullptr;
554	    for (auto &entry : entries_) {
555	      if (entry.bank_req.type != bank_req_t::Replay)
556	        continue;
557	      if (picked == nullptr || entry.seq < picked->seq)
558	        picked = &entry;
559	    }
560	    return picked;
561	  }
562	
563	  // Dequeue the next ready replay request in program order (oldest enqueue
564	  // sequence first). Coalesced accesses to the same line must replay in the
565	  // order they were issued: a store that precedes a load to the same line has
566	  // to merge its data before the load captures its response, and a load that
567	  // precedes a store must capture the pre-store line. A blanket reads-before-
568	  // writes policy gets the store-then-load case wrong — under write-allocate
569	  // the fill only carries memory's stale data, so the store's own replay is
570	  // what installs the new value.
571	  void dequeue(bank_req_t *out) {
572	    assert(ready_reqs_ > 0);
573	    mshr_entry_t *picked = nullptr;
574	    for (auto &entry : entries_) {
575	      if (entry.bank_req.type != bank_req_t::Replay)
576	        continue;
577	      if (picked == nullptr || entry.seq < picked->seq)
578	        picked = &entry;
579	    }
580	    *out = picked->bank_req;
581	    picked->bank_req.type = bank_req_t::None;
582	    --ready_reqs_;
583	    --size_;
584	  }
585	
586	  void reset() {
587	    for (auto &entry : entries_) {
588	      entry.reset();
589	    }
590	    ready_reqs_ = 0;
591	    size_ = 0;
592	  }
593	
594	private:
595	  std::vector<mshr_entry_t> entries_;
596	  uint32_t ready_reqs_;
597	  uint32_t size_;
598	};
