600	class CacheBank : public SimObject<CacheBank> {
601	public:
602	  SimChannel<MemReq> core_req_in;
603	  SimChannel<MemRsp> core_rsp_out;
604	
605	  SimChannel<MemReq> mem_req_out;
606	  SimChannel<MemRsp> mem_rsp_in;
607	
608	  CacheBank(const SimContext &ctx,
609	            const char *name,
610	            const Cache::Config &config,
611	            const params_t &params,
612	            uint32_t bank_id)
613	      : SimObject<CacheBank>(ctx, name), core_req_in(this), core_rsp_out(this), mem_req_out(this), mem_rsp_in(this), config_(config), params_(params), bank_id_(bank_id), sets_(params.sets_per_bank, set_t(params.lines_per_set, params.sectors_per_line)), mshr_(config.mshr_size), pipe_req_(TFifo<bank_req_t>::Create("", config.latency)), rand_ctr_(0), adm_seq_ctr_(0)
614	#if VX_CFG_EXT_A_ENABLED
615	      , amo_unit_(__MAX(2u, (uint32_t)VX_CFG_AMO_RS_SIZE))
616	#endif
617	  {
618	    this->on_reset();
619	  }
620	
621	  const Cache::PerfStats &perf_stats() const {
622	    return perf_stats_;
623	  }
624	
625	  // Flush API.
626	  // flush_begin() arms the bank; subsequent ticks scan all sets/ways and emit
627	  // a writeback request for every dirty line via mem_req_out (write-back only;
628	  // write-through caches have nothing to evict). flush_done() reports when the
629	  // walk finishes AND the cache is otherwise idle.
630	  void flush_begin() {
631	    if (!config_.write_back) {
632	      flushing_ = false;
633	      flush_set_idx_ = 0;
634	      flush_way_idx_ = 0;
635	      flush_sector_idx_ = 0;
636	      return;
637	    }
638	    flushing_ = true;
639	    flush_set_idx_ = 0;
640	    flush_way_idx_ = 0;
641	    flush_sector_idx_ = 0;
642	  }
643	
644	  bool flush_done() const {
645	    return !flushing_;
646	  }
647	
648	protected:
649	  void on_reset() {
650	    perf_stats_ = Cache::PerfStats();
651	    pending_mshr_size_ = 0;
652	    pending_amo_probes_ = 0;
653	    pipe_core_lines_.clear();
654	    pending_read_reqs_ = 0;
655	    pending_write_reqs_ = 0;
656	    pending_fill_reqs_ = 0;
657	    rand_ctr_ = 0;
658	    adm_seq_ctr_ = 0;
659	    for (auto &set : sets_) {
660	      set.reset();
661	    }
662	    mshr_.reset();
663	    fwd_active_ = false;
664	    fwd_set_    = 0;
665	    fwd_tag_    = 0;
666	    fwd_sector_ = 0;
667	    crsp_sent_  = false;
668	    flushing_ = false;
669	    flush_set_idx_ = 0;
670	    flush_way_idx_ = 0;
671	    flush_sector_idx_ = 0;
672	#if VX_CFG_EXT_A_ENABLED
673	    amo_unit_.reset();
674	    for (auto &e : amo_passthru_) {
675	      e = amo_passthru_entry_t{};
676	    }
677	#endif
678	  }
679	
680	  void on_tick() {
681	    // The core-response port takes one response per tick; the pipeline has
682	    // priority and the forward drain yields (crsp_sent_).
683	    crsp_sent_ = false;
684	
685	    // Process next request at the head of the pipeline.
686	    if (!pipe_req_->empty()) {
687	        this->processRequests();
688	    }
689	
690	    // Fill-forward drain: complete the read-prefix of a fill's pending chain
691	    // directly (one per tick), leaving the input slot free for new requests.
692	    // On response backpressure the head falls back to the replay path.
693	    bool fwd_consumed = false;
694	    if (fwd_active_) {
695	        fwd_consumed = this->processForward();
696	    }
697	
698	    // Accept one new input if there's room.
699	    if (!pipe_req_->full()) {
700	        this->processInputs(fwd_consumed);
701	    }
702	
703	    // flush walk: emit writebacks for dirty lines.
704	    if (flushing_) {
705	      this->processFlush();
706	    }
707	
708	    // calculate memory latency
709	    perf_stats_.mem_latency += pending_fill_reqs_;
710	  }
711	
712	private:
713	  // Pipeline front: per-tick input arbitration.
714	  //
715	  // Priority (highest → lowest):
716	  //   1) replay   — drains an already-marked Replay entry from the MSHR
717	  //                 (guaranteed hit; no miss path)
718	  //   2) fill     — memory response; installs the line and marks pending
719	  //                 MSHR entries for replay (gated on no pending replay so
720	  //                 a fill never preempts an in-flight replay's line)
721	  //   3) flush    — handled by processFlush() (separate state machine)
722	  //   4) core_req — new core request (may miss and allocate an MSHR slot)
723	  //
724	  // At most one input fires per tick. All inputs flow through pipe_req_.
725	  void processInputs(bool fwd_consumed) {
726	    // 1) replay: one chain entry leaves per tick — when the fill-forward
727	    // drain completed the head this tick, this slot goes to new core
728	    // requests instead
729	    if (mshr_.has_ready_reqs() && !fwd_consumed) {
730	      bank_req_t bank_req;
731	      mshr_.dequeue(&bank_req);
732	      pipe_req_->push(bank_req);
733	      DT(3, this->name() << " replay-deq: " << bank_req);
734	      return;
735	    }
736	
737	    // 2) fill only when no replay is pending and no forward drain is in
738	    // progress (a new fill would re-arm the window mid-chain)
739	    if (!this->mem_rsp_in.empty() && !fwd_active_) {
740	      auto &mem_rsp = this->mem_rsp_in.peek();
741	#if VX_CFG_EXT_A_ENABLED
742	      // Non-LLC AMO passthrough response: forward straight to core
743	      // without filling. The original tag was rewritten to
744	      // (mshr_capacity + pid) when the bank emitted the request from
745	      // the AmoProbe handler — that namespace partition survives
746	      // arbiter tag mangling.
747	      if (mem_rsp.tag >= amo_passthru_tag_base()
748	       && mem_rsp.tag <  amo_passthru_tag_base() + AMO_PASSTHRU_CAP) {
749	        uint32_t pid = mem_rsp.tag - amo_passthru_tag_base();
750	        auto &e = amo_passthru_.at(pid);
751	        assert(e.valid && "AMO passthru response without entry");
752	        if (this->core_rsp_out.full()) {
753	          return; // stall
754	        }
755	        MemRsp core_rsp{e.req_tag, e.cid, e.uuid};
756	        core_rsp.data = mem_rsp.data;
757	        this->core_rsp_out.send(core_rsp);
758	        DT(3, this->name() << " amo-passthru-rsp: " << core_rsp);
759	        e.valid = false;
760	        this->mem_rsp_in.pop();
761	        --pending_fill_reqs_;
762	        return;
763	      }
764	#endif
765	      uint32_t mshr_id = mem_rsp.tag;
766	      const auto &root_peek = mshr_.peek(mshr_id);
767	      bank_req_t bank_req;
768	      bank_req.reset();
769	      bank_req.type    = bank_req_t::Fill;
770	      bank_req.addr    = params_.mem_addr_sector(bank_id_, root_peek.set_id, root_peek.addr_tag, root_peek.sector_id);
771	      bank_req.hart_id     = root_peek.bank_req.hart_id;
772	      bank_req.uuid    = root_peek.bank_req.uuid;
773	      bank_req.mshr_id = mshr_id;
774	      bank_req.data    = mem_rsp.data;
775	      pipe_req_->push(bank_req);
776	      DT(3, this->name() << " fill-rsp: " << mem_rsp);
777	      this->mem_rsp_in.pop();
778	      --pending_fill_reqs_;
779	      return;
780	    }
781	
782	    // 3) core request
783	    if (!this->core_req_in.empty()) {
784	      auto &core_req = this->core_req_in.peek();
785	      // Conservative MSHR occupancy check: any request that may miss must
786	      // reserve a slot. Counts both currently-allocated entries and
787	      // in-flight pipe requests that haven't reached MSHR allocation yet.
788	      // AMO requests always need a return; at the LLC they reserve like
789	      // a load; at non-LLC they don't fill so no MSHR slot is needed
790	      // but a passthru side-table slot is.
791	      const bool is_amo = memop_is_amo(core_req.op);
792	#if VX_CFG_EXT_A_ENABLED
793	      const bool is_amo_passthru = is_amo && !config_.is_llc;
794	      if (is_amo_passthru) {
795	        // Reserve a passthru-table slot at admission, counting probes still
796	        // in the pipe. A probe that reaches the pipe head with no free slot
797	        // cannot retire, and a full pipe blocks the response processing that
798	        // frees slots — a deadlock the input gate must make unreachable.
799	        uint32_t free_slots = 0;
800	        for (const auto &e : amo_passthru_) { if (!e.valid) ++free_slots; }
801	        if (free_slots <= pending_amo_probes_) {
802	          ++perf_stats_.mshr_stalls;
803	          return;
804	        }
805	        // Age-ordering: if a fill is in flight for this AMO's line, an
806	        // older load/store missed on it and is awaiting its replay. Defer
807	        // the AMO until that access completes — otherwise the AMO's
808	        // self-invalidation removes the line after the fill installs it
809	        // but before the replay (which re-queues behind this AMO) reads
810	        // it, turning the replay into a miss.
811	        uint32_t amo_set_id   = params_.addr_set_id(core_req.addr);
812	        uint64_t amo_addr_tag = params_.addr_tag(core_req.addr);
813	        uint32_t amo_sector   = params_.addr_sector_id(core_req.addr);
814	        if (mshr_.lookup(amo_set_id, amo_addr_tag, amo_sector)) {
815	          ++perf_stats_.mshr_stalls;
816	          return;
817	        }
818	        // An older same-line access still inside the bank pipe allocates its
819	        // MSHR entry only at pipe exit; defer on those too, or the AMO
820	        // overtakes it and a younger same-address load can chain onto the
821	        // pre-AMO fill (and the fill installs a pre-AMO line).
822	        for (const auto &kv : pipe_core_lines_) {
823	          if (kv.first == amo_set_id && kv.second == amo_addr_tag) {
824	            ++perf_stats_.mshr_stalls;
825	            return;
826	          }
827	        }
828	      }
829	#else
830	      const bool is_amo_passthru = false;
831	#endif
832	      // Gate ALL non-AMO-passthru requests on MSHR occupancy because a
833	      // write-through store can need a wt-merge MSHR slot if a fill is
834	      // pending on the same line. Letting writes in past a full MSHR
835	      // causes them to stall on the wt-merge enqueue, blocking fill
836	      // responses from draining — a deadlock. Reserve at admission.
837	      bool needs_mshr = !is_amo_passthru;
838	      (void)is_amo;
839	      if (needs_mshr && (mshr_.size() + pending_mshr_size_) >= mshr_.capacity()) {
840	        ++perf_stats_.mshr_stalls;
841	        return;
842	      }
843	
844	      // Admission-time coalescing: a request whose (set,tag,sector) has a
845	      // pending MSHR chain must join it here, not enter the pipe as an
846	      // independent Core request. Deciding at pipe exit is too late — the
847	      // chain's fill can ride the pipe ahead of this request and install the
848	      // line, and the chain's replays dequeue (clearing their entries) while
849	      // this request is still in the pipe; its exit-time lookup then sees a
850	      // plain hit and it overtakes older same-line accesses. Chain fill
851	      // still pending: plain enqueue, replay() marks it. Chain draining:
852	      // enqueue + defer_to_replay. Write-through stores keep their at-miss
853	      // semantics (memory write + response now, line merge deferred).
854	      // Write-through stores are exempt: their downstream write must be
855	      // emitted at the commit stage so same-line stores reach memory in
856	      // pipeline order (an at-admission emission could overtake an older
857	      // store still riding the pipe). The pipe-exit paths order them
858	      // correctly and defer only the line merge when a chain is pending.
859	      const bool is_wt_store = (core_req.op == MemOp::ST) && !config_.write_back;
860	      if (!is_amo_passthru && !is_wt_store && mshr_.size() != 0) {
861	        uint32_t adm_set_id   = params_.addr_set_id(core_req.addr);
862	        uint64_t adm_addr_tag = params_.addr_tag(core_req.addr);
863	        uint32_t adm_sector   = params_.addr_sector_id(core_req.addr);
864	        uint32_t chain_root = 0;
865	        if (mshr_.lookup(adm_set_id, adm_addr_tag, adm_sector, &chain_root)) {
866	          bank_req_t coalesced;
867	          coalesced.reset();
868	          coalesced.adm_seq = adm_seq_ctr_++;
869	          coalesced.type    = bank_req_t::Core;
870	          coalesced.addr    = core_req.addr;
871	          coalesced.hart_id = core_req.hart_id;
872	          coalesced.uuid    = core_req.uuid;
873	          coalesced.req_tag = core_req.tag;
874	          coalesced.write   = (core_req.op == MemOp::ST);
875	          coalesced.op      = core_req.op;
876	          coalesced.data    = core_req.data;
877	          coalesced.byteen  = core_req.byteen;
878	          coalesced.flags   = core_req.flags;
879	          assert(!mshr_.full());
880	          int id = mshr_.enqueue(coalesced, adm_set_id, adm_addr_tag, adm_sector);
881	          // Chain draining (no other entry awaiting the fill): nothing will
882	          // mark our entry — make it replay-ready ourselves, seq-ordered
883	          // behind the in-flight replays.
884	          if (!mshr_.has_pending_fill(adm_set_id, adm_addr_tag, adm_sector, id)) {
885	            mshr_.defer_to_replay(id);
886	          }
887	          DT(3, this->name() << " mshr-coalesce@admission: " << coalesced);
888	          // Chain joiners count as misses, matching the pipe-exit chaining
889	          // they replace.
890	          if (core_req.is_write()) {
891	            ++perf_stats_.writes;
892	            ++perf_stats_.write_misses;
893	          } else {
894	            ++perf_stats_.reads;
895	            ++perf_stats_.read_misses;
896	          }
897	          this->core_req_in.pop();
898	          return;
899	        }
900	      }
901	
902	      bank_req_t bank_req;
903	      bank_req.reset();
904	      bank_req.adm_seq = adm_seq_ctr_++;
905	      bank_req.type    = is_amo_passthru ? bank_req_t::AmoProbe : bank_req_t::Core;
906	      bank_req.addr    = core_req.addr;
907	      bank_req.hart_id = core_req.hart_id;
908	      bank_req.uuid    = core_req.uuid;
909	      bank_req.req_tag = core_req.tag;
910	      // bank_req.write means "route through the cache write path" — true only
911	      // for plain stores. AMOs (op == AMO_SC / AMO RMW) are write-bearing
912	      // semantically (memop_is_write returns true) but use the dedicated AMO
913	      // commit path, not the write-path; keep bank_req.write false for them.
914	      bank_req.write   = (core_req.op == MemOp::ST);
915	      bank_req.op      = core_req.op;
916	      bank_req.data    = core_req.data;
917	      bank_req.byteen  = core_req.byteen;
918	      bank_req.flags   = core_req.flags;
919	      pipe_req_->push(bank_req);
920	      DT(3, this->name() << " core-req: " << core_req);
921	      // pending_mshr_size_ tracks Core-typed in-flight requests so the
922	      // MSHR pre-reservation in processInputs is conservative. AmoProbe
923	      // doesn't allocate an MSHR slot (no fill on the response), so it
924	      // stays out of this counter.
925	      if (!is_amo_passthru) {
926	        ++pending_mshr_size_;
927	        pipe_core_lines_.emplace_back(params_.addr_set_id(core_req.addr),
928	                                      params_.addr_tag(core_req.addr));
929	      }
930	#if VX_CFG_EXT_A_ENABLED
931	      if (is_amo_passthru) ++pending_amo_probes_;
932	#endif
933	      if (core_req.is_write()) ++perf_stats_.writes;
934	      else                ++perf_stats_.reads;
935	      this->core_req_in.pop();
936	      return;
937	    }
938	  }
