940	  // Fill-forward drain: complete the oldest ready replay directly when it is
941	  // a plain read on the armed chain — no pipeline traversal, and the input
942	  // slot stays free for new requests. The first write/AMO head closes the
943	  // window; it and every later chain entry drain through the regular replay
944	  // path, preserving program order (an older store must merge its data
945	  // before a younger same-line read captures its response). Forwarded reads
946	  // skip the replacement-state update: recency is tracked by pipelined
947	  // lookups only.
948	  bool processForward() {
949	    if (!mshr_.has_ready_reqs()) {
950	      fwd_active_ = false; // chain drained
951	      return false;
952	    }
953	    const auto *head = mshr_.peek_next_replay();
954	    if (head == nullptr) {
955	      return false;
956	    }
957	    if (head->set_id != fwd_set_
958	     || head->addr_tag != fwd_tag_
959	     || head->sector_id != fwd_sector_
960	     || head->bank_req.write
961	     || memop_is_atomic(head->bank_req.op)) {
962	      fwd_active_ = false;
963	      return false;
964	    }
965	    // The armed sector is normally resident (the fill just installed it); a
966	    // concurrent invalidate falls back to the replay path, which re-fetches.
967	    auto &set = sets_.at(head->set_id);
968	    int present_id = set.find_resident(head->addr_tag);
969	    uint32_t sector_id = head->sector_id;
970	    if (present_id == -1 || !set.lines.at(present_id).sectors.at(sector_id).valid) {
971	      fwd_active_ = false;
972	      return false;
973	    }
974	    if (crsp_sent_ || this->core_rsp_out.full()) {
975	      return false; // the head falls back to the replay path this tick
976	    }
977	    bank_req_t req;
978	    mshr_.dequeue(&req);
979	    MemRsp rsp{req.req_tag, req.hart_id, req.uuid};
980	    rsp.data = set.lines.at(present_id).sectors.at(sector_id).data;
981	    this->core_rsp_out.send(rsp);
982	    DT(3, this->name() << " fwd-rsp: " << rsp);
983	    return true;
984	  }
