986	#if VX_CFG_EXT_A_ENABLED
987	  // AMO commit at the LLC bank. Returns false if the cycle stalls
988	  // (caller leaves bank_req at the head of pipe_req_); returns true
989	  // when the commit completes. Collects all stall conditions before
990	  // any mutation.
991	  bool commitAmo(const bank_req_t &bank_req, set_t &set, int hit_id, uint32_t set_id) {
992	    const uint32_t sector_id = params_.addr_sector_id(bank_req.addr);
993	    auto &hit_sec = set.lines.at(hit_id).sectors.at(sector_id);
994	    const uint64_t line_addr = (bank_req.addr >> config_.L) << config_.L;
995	    const uint32_t byte_off  = (uint32_t)(bank_req.addr & (VX_CFG_MEM_BLOCK_SIZE - 1));
996	    const MemOp    op        = bank_req.op;
997	    // Width derived from byteen popcount (RVA mandates natural alignment, so
998	    // byteen is contiguous: popcount==8 ⇒ .D, popcount==4 ⇒ .W).
999	    const uint8_t  width     = (__builtin_popcountll(bank_req.byteen) >= 8) ? 3 : 2;
1000	    const uint32_t hid       = bank_req.hart_id;
1001	    // rhs is the lane's rs2 packed into bank_req.data at byte_off (LSU builds
1002	    // this the same way as for stores; mem_coalescer also merges it for AMOs).
1003	    const uint64_t rhs       = bank_req.data
1004	                             ? amo_load_word(bank_req.data->data(), byte_off, width)
1005	                             : 0ull;
1006	    // MIN/MAX signedness: signed by default, unsigned per flag.
1007	    const bool unsigned_minmax = bank_req.flags.amo_unsigned;
1008	
1009	    const bool sc_fail  = (op == MemOp::AMO_SC) && !amo_unit_.check(hid, line_addr);
1010	    const bool do_store = (op != MemOp::AMO_LR) && !sc_fail;
1011	
1012	    // Stall checks (collect all before mutating).
1013	    if (this->core_rsp_out.full())
1014	      return false;
1015	    if (do_store && !config_.write_back && this->mem_req_out.full())
1016	      return false;
1017	
1018	    // Pure compute: read old word, derive new and ret.
1019	    uint64_t old_word = 0;
1020	    if (hit_sec.data) {
1021	      old_word = amo_load_word(hit_sec.data->data(), byte_off, width);
1022	    }
1023	    auto rmw = amo_unit_.compute(op, width, old_word, rhs, unsigned_minmax);
1024	
1025	    // Build response payload: a fresh block with the relevant word at byte_off.
1026	    // For LR/AMO* the word carries old_word (LSU sext at width gives rd).
1027	    // For SC it carries 0 (success) or 1 (failure).
1028	    auto rsp_block = make_mem_block();
1029	    std::memset(rsp_block->data(), 0, rsp_block->size());
1030	    uint64_t rsp_word = (op == MemOp::AMO_SC) ? (sc_fail ? 1ull : 0ull)
1031	                                            : rmw.ret_word;
1032	    amo_store_word(rsp_block->data(), byte_off, width, rsp_word);
1033	
1034	    // Reservation update before commit so a same-cycle invalidate
1035	    // from the store path doesn't kill our just-installed entry.
1036	    if (op == MemOp::AMO_LR) {
1037	      amo_unit_.reserve(hid, line_addr);
1038	    } else if (op == MemOp::AMO_SC) {
1039	      // RVA: SC always invalidates the reservation, success or fail.
1040	      amo_unit_.clear(hid, line_addr);
1041	    }
1042	
1043	    if (do_store) {
1044	      // Merge the new word at byte_off into the line.
1045	      auto store_block = make_mem_block();
1046	      std::memset(store_block->data(), 0, store_block->size());
1047	      amo_store_word(store_block->data(), byte_off, width, rmw.new_word);
1048	      uint64_t byteen = amo_byteen(byte_off, width);
1049	      sector_merge(hit_sec, store_block, byteen);
1050	      if (config_.write_back) {
1051	        hit_sec.dirty = true;
1052	        hit_sec.dirty_mask |= byteen;
1053	      } else {
1054	        // Write-through: emit a write of the merged word downstream.
1055	        MemReq w;
1056	        w.addr   = params_.mem_addr_sector(bank_id_, set_id, params_.addr_tag(bank_req.addr), sector_id);
1057	        w.op = MemOp::ST;
1058	        w.hart_id    = bank_req.hart_id;
1059	        w.uuid   = bank_req.uuid;
1060	        w.data   = store_block;
1061	        w.byteen = byteen;
1062	        this->mem_req_out.send(w);
1063	        DT(3, this->name() << " amo-writethrough: " << w);
1064	      }
1065	      // Break other harts' reservations on this line.
1066	      amo_unit_.invalidate(line_addr, /*except=*/hid);
1067	    }
1068	
1069	    // Send AMO response.
1070	    MemRsp rsp{bank_req.req_tag, bank_req.hart_id, bank_req.uuid};
1071	    rsp.data = rsp_block;
1072	    this->core_rsp_out.send(rsp);
1073	    crsp_sent_ = true;
1074	    DT(3, this->name() << " amo-rsp op=" << op << " sc_fail=" << sc_fail << ": " << rsp);
1075	    return true;
1076	  }
1077	#endif
