1079	  // Pipeline tail: process the head of pipe_req_ — at most one bank_req_t per tick.
1080	
1081	  // Emit a write-through store downstream, with the optional core response.
1082	  // All backpressure is checked before any send, so a false return stalls
1083	  // the caller with no partial effects.
1084	  bool emitWritethrough(uint32_t set_id, uint64_t addr_tag, uint32_t sector_id,
1085	                        uint64_t full_addr, uint32_t hart_id, uint64_t uuid,
1086	                        const std::shared_ptr<mem_block_t>& data, uint64_t byteen,
1087	                        bool need_rsp, uint64_t rsp_tag) {
1088	    __unused(full_addr);
1089	    if (this->mem_req_out.full()) {
1090	      return false;
1091	    }
1092	    if (need_rsp && this->core_rsp_out.full()) {
1093	      return false;
1094	    }
1095	    MemReq w;
1096	    w.addr    = params_.mem_addr_sector(bank_id_, set_id, addr_tag, sector_id);
1097	    w.op      = MemOp::ST;
1098	    w.hart_id = hart_id;
1099	    w.uuid    = uuid;
1100	    w.data    = data;
1101	    w.byteen  = byteen;
1102	    this->mem_req_out.send(w);
1103	    DT(3, this->name() << " writethrough: " << w);
1104	#if VX_CFG_EXT_A_ENABLED
1105	    // Committed write: break other harts' reservations.
1106	    if (config_.is_llc) {
1107	      uint64_t line_addr = (full_addr >> config_.L) << config_.L;
1108	      amo_unit_.invalidate(line_addr, /*except=*/hart_id);
1109	    }
1110	#endif
1111	    if (need_rsp) {
1112	      MemRsp rsp{rsp_tag, hart_id, uuid};
1113	      this->core_rsp_out.send(rsp);
1114	      crsp_sent_ = true;
1115	      DT(3, this->name() << " core-rsp: " << rsp);
1116	    }
1117	    return true;
1118	  }
