1120	  void processRequests() {
1121	    const bank_req_t &bank_req = pipe_req_->peek();
1122	
1123	    // Stores get a response when (a) the cache is configured to always emit
1124	    // them (config_.write_reponse, global), or (b) the request opts in via
1125	    // MEM_FLAG_STRSP (per-request). Loads/AMOs always have a response.
1126	    auto need_core_rsp = [&](const bank_req_t &req) {
1127	      return (!req.write) || config_.write_reponse || req.flags.strsp;
1128	    };
1129	
1130	    switch (bank_req.type) {
1131	    case bank_req_t::None:
1132	      pipe_req_->pop();
1133	      return;
1134	
1135	#if VX_CFG_EXT_A_ENABLED
1136	    case bank_req_t::AmoProbe: {
1137	      // Non-LLC AMO passthrough. Probe the local line first so any
1138	      // cached copy doesn't shadow the LLC's view: dirty line →
1139	      // writeback; any hit → invalidate. Then forward the original AMO
1140	      // MemReq downstream so the response routes back to core_rsp_out
1141	      // without installing a fill.
1142	      assert(!config_.is_llc && "AmoProbe at LLC is a wiring bug");
1143	      uint32_t set_id    = params_.addr_set_id(bank_req.addr);
1144	      uint64_t addr_tag  = params_.addr_tag(bank_req.addr);
1145	      uint32_t sector_id = params_.addr_sector_id(bank_req.addr);
1146	      auto &set          = sets_.at(set_id);
1147	      int32_t free_id = -1, repl_id = 0;
1148	      int present_id = set.tag_match(addr_tag, config_.repl_policy, rand_ctr_, &free_id, &repl_id);
1149	      // Probe targets only the sector the AMO addresses; other sectors of the
1150	      // same line are independent and stay resident.
1151	      int hit_id = (present_id != -1 && set.lines.at(present_id).sectors.at(sector_id).valid) ? present_id : -1;
1152	      const bool hit   = (hit_id != -1);
1153	      const bool dirty = hit && set.lines.at(hit_id).sectors.at(sector_id).dirty;
1154	
1155	      // Stall checks: writeback (if dirty) AND the AMO forward both
1156	      // need a mem_req_out slot.
1157	      const uint32_t out_slots_needed = (dirty ? 1u : 0u) + 1u;
1158	      if (this->mem_req_out.size() + out_slots_needed > this->mem_req_out.capacity()) {
1159	        return; // stall
1160	      }
1161	      // Pre-allocate a passthru-table slot before mutating state.
1162	      uint32_t pid = AMO_PASSTHRU_CAP;
1163	      for (uint32_t i = 0; i < AMO_PASSTHRU_CAP; ++i) {
1164	        if (!amo_passthru_.at(i).valid) { pid = i; break; }
1165	      }
1166	      if (pid == AMO_PASSTHRU_CAP) {
1167	        // Unreachable: admission reserves a slot per in-pipe probe. Kept as
1168	        // a defensive stall.
1169	        return;
1170	      }
1171	
1172	      if (dirty) {
1173	        auto &sec = set.lines.at(hit_id).sectors.at(sector_id);
1174	        MemReq wb;
1175	        wb.addr   = params_.mem_addr_sector(bank_id_, set_id, set.lines.at(hit_id).tag, sector_id);
1176	        wb.op = MemOp::ST;
1177	        wb.hart_id    = bank_req.hart_id;
1178	        wb.uuid   = bank_req.uuid;
1179	        wb.data   = sec.data;
1180	        wb.byteen = sec.dirty_mask;
1181	        this->mem_req_out.send(wb);
1182	        DT(3, this->name() << " amo-probe-wb: " << wb);
1183	        ++perf_stats_.evictions;
1184	      }
1185	      if (hit) {
1186	        set.lines.at(hit_id).sectors.at(sector_id).reset();
1187	      }
1188	
1189	      // Forward AMO downstream. Tag is rewritten so the response
1190	      // doesn't collide with the MSHR tag namespace.
