1197	      amo_fwd.addr   = bank_req.addr;
1198	      // op already set below; default-construct sets MemOp::LD which we override.
1199	      amo_fwd.tag    = amo_passthru_tag_base() + pid;
1200	      amo_fwd.hart_id = bank_req.hart_id;
1201	      amo_fwd.uuid    = bank_req.uuid;
1202	      amo_fwd.op      = bank_req.op;
1203	      amo_fwd.byteen  = bank_req.byteen;  // carries width info (popcount-derived at LLC)
1204	      amo_fwd.data    = bank_req.data;    // carries rhs (extracted at LLC)
1205	      amo_fwd.flags   = bank_req.flags;   // carry amo_unsigned (signed vs unsigned MIN/MAX)
