1223	      uint32_t sector_id = params_.addr_sector_id(bank_req.addr);
1224	      auto &set          = sets_.at(set_id);
1225	
1226	      int resident_id = set.find_resident(addr_tag);
1227	      const bool is_refill = (resident_id != -1);
1228	
1229	      int line_id;
1230	      if (is_refill) {
1231	        line_id = resident_id; // add a sector to the resident copy; no eviction
1232	      } else {
