1234	        line_id = set.select_victim(config_.repl_policy, rand_ctr_, &free_id, &repl_id);
1235	        auto &victim_line = set.lines.at(line_id);
1236	
1237	        // Count the victim's dirty sectors; the egress queue must accept all
1238	        // their writeback beats before we mutate any state.
1239	        uint32_t wb_count = 0;
1240	        if (config_.write_back) {
1241	          for (const auto &s : victim_line.sectors)
1242	            if (s.valid && s.dirty) ++wb_count;
1243	        }
1244	        if (wb_count > 0 && (this->mem_req_out.size() + wb_count) > this->mem_req_out.capacity())
