1253	        // Emit one writeback per dirty sector.
1254	        for (uint32_t s = 0; s < victim_line.sectors.size(); ++s) {
1255	          auto &sec = victim_line.sectors.at(s);
1256	          if (!(config_.write_back && sec.valid && sec.dirty))
1257	            continue;
1258	          MemReq wb;
1259	          wb.addr   = params_.mem_addr_sector(bank_id_, set_id, victim_line.tag, s);
1260	          wb.op     = MemOp::ST;
1261	          wb.hart_id = bank_req.hart_id;
1262	          wb.uuid   = bank_req.uuid;
1263	          wb.data   = sec.data;
1264	          wb.byteen = sec.dirty_mask;
1265	          this->mem_req_out.send(wb);
1266	          DT(3, this->name() << " writeback: " << wb);
1267	          ++perf_stats_.evictions;
1268	        }
