1569	  void processFlush() {
1570	    // Wait for in-flight requests to drain before walking lines, otherwise an
1571	    // outstanding fill could install a fresh line behind our scan and leave
1572	    // a dirty victim un-evicted.
1573	    if (pending_fill_reqs_ != 0
1574	     || !pipe_req_->empty()
1575	     || !mshr_.empty()) {
1576	      return;
1577	    }
1578	    while (flush_set_idx_ < params_.sets_per_bank) {
1579	      auto &set = sets_.at(flush_set_idx_);
1580	      while (flush_way_idx_ < set.lines.size()) {
1581	        auto &line = set.lines.at(flush_way_idx_);
1582	        // Emit one writeback per dirty sector (resumable across stalls).
1583	        while (flush_sector_idx_ < line.sectors.size()) {
1584	          auto &sec = line.sectors.at(flush_sector_idx_);
1585	          if (sec.valid && sec.dirty) {
1586	            if (this->mem_req_out.full())
1587	              return; // stall — resume at this sector next cycle
1588	            MemReq mem_req;
1589	            mem_req.addr = params_.mem_addr_sector(bank_id_, flush_set_idx_, line.tag, flush_sector_idx_);
1590	            mem_req.op   = MemOp::ST;
1591	            mem_req.data = sec.data;
1592	            mem_req.byteen = sec.dirty_mask;
1593	            this->mem_req_out.send(mem_req);
1594	            DT(3, this->name() << " flush-wb: " << mem_req);
1595	            ++perf_stats_.evictions;
1596	            sec.dirty = false;
1597	            sec.dirty_mask = 0;
1598	          }
1599	          ++flush_sector_idx_;
1600	        }
1601	        flush_sector_idx_ = 0;
1602	        ++flush_way_idx_;
1603	      }
1604	      ++flush_set_idx_;
1605	      flush_way_idx_ = 0;
1606	    }
1607	    flushing_ = false;
1608	    DT(3, this->name() << " flush-done");
1609	  }
