1685	    char sname[100];
1686	
1687	    uint32_t num_banks = (1 << config.B);
1688	
1689	    if (config_.bypass) {
1690	      snprintf(sname, 100, "%s-bypass_arb", simobject->name().c_str());
1691	      auto bypass_arb = MemArbiter::Create(sname, ArbiterType::RoundRobin, config_.num_inputs, config_.mem_ports);
1692	      for (uint32_t i = 0; i < config_.num_inputs; ++i) {
1693	        simobject->core_req_in.at(i).bind(&bypass_arb->ReqIn.at(i));
1694	        bypass_arb->RspOut.at(i).bind(&simobject->core_rsp_out.at(i));
1695	      }
1696	      for (uint32_t i = 0; i < config_.mem_ports; ++i) {
1697	        bypass_arb->ReqOut.at(i).bind(&simobject->mem_req_out.at(i));
1698	        simobject->mem_rsp_in.at(i).bind(&bypass_arb->RspIn.at(i));
1699	      }
1700	      return;
1701	    }
1702	
1703	    // create non-cacheable arbiter
1704	    for (uint32_t i = 0; i < config_.mem_ports; ++i) {
1705	      snprintf(sname, 100, "%s-nc_arb%d", simobject->name().c_str(), i);
1706	      nc_mem_arbs_.at(i) = MemArbiter::Create(sname, ArbiterType::Priority, 2, 1);
1707	    }
1708	
1709	    // Connect non-cacheable arbiter output port 0 to outgoing memory ports
1710	    for (uint32_t i = 0; i < config_.mem_ports; ++i) {
1711	      nc_mem_arbs_.at(i)->ReqOut.at(0).bind(&simobject->mem_req_out.at(i));
1712	      simobject->mem_rsp_in.at(i).bind(&nc_mem_arbs_.at(i)->RspIn.at(0));
1713	    }
1714	
1715	    // Create bank's memory arbiter
1716	    snprintf(sname, 100, "%s-mem_arb", simobject->name().c_str());
1717	    auto bank_mem_arb = MemArbiter::Create(sname, ArbiterType::RoundRobin, num_banks, config_.mem_ports);
1718	
1719	    // Connect bank's memory arbiter to non-cacheable arbiter's input port 0
1720	    for (uint32_t i = 0; i < config_.mem_ports; ++i) {
1721	      bank_mem_arb->ReqOut.at(i).bind(&nc_mem_arbs_.at(i)->ReqIn.at(0));
1722	      nc_mem_arbs_.at(i)->RspOut.at(0).bind(&bank_mem_arb->RspIn.at(i));
1723	    }
1724	
1725	    // Create bank's core crossbar
1726	    snprintf(sname, 100, "%s-core_xbar", simobject->name().c_str());
1727	    bank_core_xbar_ = MemCrossBar::Create(sname, ArbiterType::RoundRobin, config_.num_inputs, num_banks,
1728	                                          [&](const MemCrossBar::ReqType &req) {
1729	                                            return params_.addr_bank_id(req.addr);
1730	                                          });
1731	
1732	    // Create cache banks
1733	    for (uint32_t i = 0, n = num_banks; i < n; ++i) {
1734	      snprintf(sname, 100, "%s-bank%d", simobject->name().c_str(), i);
1735	      banks_.at(i) = CacheBank::Create(sname, config, params_, i);
1736	
1737	      // bind core ports
1738	      bank_core_xbar_->ReqOut.at(i).bind(&banks_.at(i)->core_req_in);
1739	      banks_.at(i)->core_rsp_out.bind(&bank_core_xbar_->RspIn.at(i));
1740	
1741	      // bind memory ports
1742	      banks_.at(i)->mem_req_out.bind(&bank_mem_arb->ReqIn.at(i));
1743	      bank_mem_arb->RspOut.at(i).bind(&banks_.at(i)->mem_rsp_in);
1744	    }
1745	  }
1746	
1747	  void reset() {
1748	    if (config_.bypass)
1749	      return;
1750	    // calculate cache initialization cycles
1751	    init_cycles_ = params_.sets_per_bank;
1752	  }
1753	
1754	  void tick() {
1755	    if (config_.bypass)
1756	      return;
1757	
1758	    // wait on cache initialization cycles
1759	    if (init_cycles_ != 0) {
1760	      --init_cycles_;
1761	      DT(3, simobject_->name() << " init: line=" << init_cycles_);
1762	      return;
1763	    }
1764	
1765	    // handle cache bypasss responses
1766	    for (uint32_t i = 0, n = config_.mem_ports; i < n; ++i) {
1767	      // Forward non-cacheable arbiter's output (1) to core response ports
1768	      auto &bypass = nc_mem_arbs_.at(i)->RspOut.at(1);
1769	      if (!bypass.empty()) {
1770	        auto &mem_rsp = bypass.peek();
1771	        if (this->processBypassResponse(mem_rsp)) {
1772	          bypass.pop();
1773	        }
1774	      }
1775	    }
1776	
1777	    // schedule core responses
1778	    for (uint32_t req_id = 0, n = config_.num_inputs; req_id < n; ++req_id) {
1779	      auto &bank_rsp = bank_core_xbar_->RspOut.at(req_id);
1780	      if (bank_rsp.empty())
1781	        continue;
1782	      auto &core_rsp = bank_rsp.peek();
1783	      if (simobject_->core_rsp_out.at(req_id).try_send(core_rsp, 0)) {
1784	        DT(3, simobject_->name() << " core-rsp: " << core_rsp);
1785	        bank_rsp.pop();
1786	      }
1787	    }
1788	
1789	    // schedule core requests
1790	    for (uint32_t req_id = 0, n = config_.num_inputs; req_id < n; ++req_id) {
1791	      auto &core_req_in = simobject_->core_req_in.at(req_id);
1792	      if (core_req_in.empty())
1793	        continue;
1794	      auto &core_req = core_req_in.peek();
1795	      if (core_req.flags.io) {
1796	        if (this->processBypassRequest(core_req, req_id)) {
1797	          core_req_in.pop();
1798	        }
1799	      } else {
1800	        if (bank_core_xbar_->ReqIn.at(req_id).try_send(core_req, 0)) {
1801	          core_req_in.pop();
1802	        }
1803	      }
1804	    }
1805	  }
1806	
1807	  PerfStats perf_stats() const {
1808	    PerfStats perf_stats;
1809	    if (!config_.bypass) {
1810	      for (const auto &bank : banks_) {
1811	        perf_stats += bank->perf_stats();
1812	      }
1813	      perf_stats.bank_stalls = bank_core_xbar_->collisions();
1814	    }
1815	    return perf_stats;
1816	  }
1817	
1818	  void flush_begin() {
1819	    if (config_.bypass) return;
1820	    for (auto &bank : banks_) {
1821	      bank->flush_begin();
1822	    }
1823	  }
1824	
1825	  bool flush_done() const {
1826	    if (config_.bypass) return true;
1827	    for (const auto &bank : banks_) {
1828	      if (!bank->flush_done()) return false;
1829	    }
1830	    return true;
1831	  }
1832	
1833	private:
1834	
1835	  bool processBypassResponse(const MemRsp &mem_rsp) {
1836	    // core response backpressure check
1837	    uint32_t req_id = mem_rsp.tag & ((1 << params_.log2_num_inputs) - 1);
1838	    if (simobject_->core_rsp_out.at(req_id).full())
1839	      return false; // stall
1840	    uint64_t tag = mem_rsp.tag >> params_.log2_num_inputs;
1841	    MemRsp core_rsp{tag, mem_rsp.hart_id, mem_rsp.uuid};
1842	    core_rsp.data = mem_rsp.data;  // forward TLM payload through bypass
1843	    simobject_->core_rsp_out.at(req_id).send(core_rsp, 0);
1844	    DT(3, simobject_->name() << " bypass-core-rsp: " << core_rsp);
1845	    return true;
1846	  }
1847	
1848	  bool processBypassRequest(const MemReq &core_req, uint32_t req_id) {
1849	    // Push core request to non-cacheable arbiter's input (1)
1850	    uint32_t mem = req_id % config_.mem_ports;
1851	    if (nc_mem_arbs_.at(mem)->ReqIn.at(1).full())
1852	      return false; // stall
1853	    MemReq mem_req(core_req);
1854	    mem_req.tag = (core_req.tag << params_.log2_num_inputs) + req_id;
1855	    nc_mem_arbs_.at(mem)->ReqIn.at(1).send(mem_req, 0);
1856	    DT(3, simobject_->name() << " bypass-dram-req: " << mem_req);
1857	    return true;
1858	  }
1859	
1860	  Cache *const simobject_;
1861	  Config config_;
1862	  params_t params_;
1863	  std::vector<CacheBank::Ptr> banks_;
1864	  MemArbiter::Ptr bank_arb_;
1865	  std::vector<MemArbiter::Ptr> nc_mem_arbs_;
1866	  MemCrossBar::Ptr bank_core_xbar_;
1867	  uint32_t init_cycles_;
1868	};
1869	
1870	///////////////////////////////////////////////////////////////////////////////
1871	
1872	Cache::Cache(const SimContext &ctx, const char *name, const Config &config)
1873	    : SimObject<Cache>(ctx, name), core_req_in(config.num_inputs, this), core_rsp_out(config.num_inputs, this), mem_req_out(config.mem_ports, this), mem_rsp_in(config.mem_ports, this), impl_(new Impl(this, config)) {}
1874	
1875	Cache::~Cache() {
1876	  delete impl_;
1877	}
1878	
1879	void Cache::on_reset() {
1880	  impl_->reset();
1881	}
1882	
1883	void Cache::on_tick() {
1884	  impl_->tick();
1885	}
1886	
1887	Cache::PerfStats Cache::perf_stats() const {
1888	  return impl_->perf_stats();
1889	}
1890	
1891	void Cache::flush_begin() {
1892	  impl_->flush_begin();
1893	}
1894	
1895	bool Cache::flush_done() const {
1896	  return impl_->flush_done();
1897	}
1898

