14	`include "VX_cache_define.vh"
15	
16	module VX_cache_bank import VX_gpu_pkg::*; #(
17	    parameter `STRING INSTANCE_ID= "",
18	    parameter BANK_ID           = 0,
19	    parameter NUM_REQS          = 1,
20	    parameter CACHE_SIZE        = 1024,     // cache size in bytes
21	    parameter LINE_SIZE         = 16,       // line size in bytes
22	    parameter NUM_BANKS         = 1,
23	    parameter NUM_WAYS          = 1,
24	    parameter WORD_SIZE         = 4,        // word size in bytes
25	    parameter SECTOR_SIZE       = LINE_SIZE,// sector (fill/eviction granule); = LINE_SIZE => 1 sector
26	    parameter CRSQ_SIZE         = 0,        // extra core-response queue slots over minimum
27	    parameter MSHR_SIZE         = 1,        // miss reservation queue size
28	    parameter MRSQ_SIZE         = 1,        // memory response queue size (sized at wrapper)
29	    parameter MREQ_SIZE         = 0,        // memory request queue size (0 = derived minimum)
30	    parameter WRITE_ENABLE      = 1,
31	    parameter WRITEBACK         = 0,
32	    parameter DIRTY_BYTES       = 0,
33	    parameter REPL_POLICY       = `CS_REPL_FIFO,
34	    parameter TAG_WIDTH         = UUID_WIDTH + 1,
35	    parameter CORE_OUT_BUF      = 0,
36	    parameter MEM_OUT_BUF       = 0,
37	    parameter IS_LLC            = 0,        // last-level cache: AMOs commit locally here
38	    parameter AMO_ENABLE        = 0,        // synthesize atomic-op logic
39	    parameter LATENCY           = 2,        // pipeline depth; >2 defers the data array to break the tag->data path
40	    parameter MSHR_ADDR_WIDTH   = `LOG2UP(MSHR_SIZE),
41	    parameter MEM_TAG_WIDTH     = UUID_WIDTH + MSHR_ADDR_WIDTH,
42	    parameter REQ_SEL_WIDTH     = `UP(`CS_REQ_SEL_BITS),
43	    parameter WORD_SEL_WIDTH    = `UP(`CS_WORD_SEL_BITS)
44	) (
45	    input wire clk,
46	    input wire reset,
47	
48	`ifdef PERF_ENABLE
49	    output wire perf_read_miss,
50	    output wire perf_write_miss,
51	    output wire perf_evictions,
52	    output wire perf_mshr_stall,
53	`endif
54	
55	    // Core request
56	    input wire                          core_req_valid,
57	    input wire [`CS_LINE_ADDR_WIDTH-1:0] core_req_addr,
58	    input wire                          core_req_rw,
59	    input wire [WORD_SEL_WIDTH-1:0]     core_req_wsel,
60	    input wire [WORD_SIZE-1:0]          core_req_byteen,
61	    input wire [`CS_WORD_WIDTH-1:0]     core_req_data,
62	    input wire [TAG_WIDTH-1:0]          core_req_tag,
63	    input wire [REQ_SEL_WIDTH-1:0]      core_req_idx,
64	    input wire [`UP(MEM_ATTR_WIDTH)-1:0] core_req_attr,
65	    output wire                         core_req_ready,
66	
67	    // Core response
68	    output wire                         core_rsp_valid,
69	    output wire [`CS_WORD_WIDTH-1:0]    core_rsp_data,
70	    output wire [TAG_WIDTH-1:0]         core_rsp_tag,
71	    output wire [REQ_SEL_WIDTH-1:0]     core_rsp_idx,
72	    input  wire                         core_rsp_ready,
73	
74	    // Memory request (sector-granular; = line when 1 sector/line)
75	    output wire                         mem_req_valid,
76	    output wire [`CS_LINE_SECTOR_ADDR_WIDTH-1:0] mem_req_addr,
77	    output wire                         mem_req_rw,
78	    output wire [SECTOR_SIZE-1:0]       mem_req_byteen,
79	    output wire [`CS_SECTOR_WIDTH-1:0]  mem_req_data,
80	    output wire [MEM_TAG_WIDTH-1:0]     mem_req_tag,
81	    output wire [`UP(MEM_ATTR_WIDTH)-1:0] mem_req_attr,
82	    input  wire                         mem_req_ready,
83	
84	    // Memory response
85	    input wire                          mem_rsp_valid,
86	    input wire [`CS_SECTOR_WIDTH-1:0]   mem_rsp_data,
87	    input wire [MEM_TAG_WIDTH-1:0]      mem_rsp_tag,
88	    output wire                         mem_rsp_ready,
89	
90	    // Flush
91	    input wire                          flush_begin,
92	    input wire [`UP(UUID_WIDTH)-1:0]    flush_uuid,
93	    output wire                         flush_end
94	);
95	    localparam PIPELINE_STAGES = LATENCY;
96	    localparam PIPE_EX = LATENCY - 2;       // extra data-deferral stages (0 = classic 2-stage)
97	    // mem-req queue depth (pow2): max of pipeline floor (2*PIPELINE) and writeback reservation (MSHR), plus MREQ_SIZE extra slots.
98	    // A writeback cache emits an eviction request alongside the fill on a dirty miss, so up to MSHR_SIZE writebacks can
99	    // enqueue at once (one per outstanding miss); reserving MSHR_SIZE slots keeps the queue from stalling the fill drain that frees them.
100	    localparam MREQ_QUEUE_SIZE = 1 << `CLOG2(`MAX(2 * PIPELINE_STAGES, WRITEBACK ? MSHR_SIZE : 0) + MREQ_SIZE);
101	    // core-rsp queue depth (pow2): registered-skid minimum (2) plus CRSQ_SIZE extra slots
102	    localparam CRSQ_QUEUE_SIZE = 1 << `CLOG2(2 + CRSQ_SIZE);
103	    `STATIC_ASSERT(LATENCY >= 2, ("invalid parameter: cache bank LATENCY must be >= 2"))
