106	    // ========================================================================
107	    // Pipeline payload types
108	    //
109	    // The request travels as a struct and the S0-computed lookup results are a
110	    // separate `lookup_t` delta, composed into `commit_t` for the response /
111	    // memory-request stage. Fill data never rides the pipeline: the sector is
112	    // staged in the fill buffer at accept and feeds the data array directly,
113	    // so `data_t` carries only the word payload and `tag_matches`.
114	    //   sel -> S0     : data_t  (st0)            -- request + word payload
115	    //   S0  -> stD    : data_t  (stD)            -- drives the data array
116	    //   S0  -> S1->stC: commit_t (st1, stC)      -- request + lookup delta
117	    // `way_idx` and `mshr_id` are reused across stages (flush_way/replay_id at
118	    // select; resolved way / allocated id at commit). PIPE_EX=0 collapses
119	    // stD->S0 and stC->S1: the classic 2-stage bank.
120	    // ========================================================================
121	    typedef struct packed {
122	        logic                           valid, is_init, is_fill, is_flush, is_creq, is_replay, is_passthru_fill, rw;
123	        logic [`UP(MEM_ATTR_WIDTH)-1:0] attr;
124	        logic [`CS_WAY_SEL_WIDTH-1:0]   way_idx;     // flush_way @sel, resolved way @S1
125	        logic [`CS_LINE_ADDR_WIDTH-1:0] addr;
126	        logic [WORD_SIZE-1:0]           byteen;
127	        logic [WORD_SEL_WIDTH-1:0]      word_idx;
128	        logic [REQ_SEL_WIDTH-1:0]       req_idx;
129	        logic [TAG_WIDTH-1:0]           tag;
130	        logic [MSHR_ADDR_WIDTH-1:0]     mshr_id;     // replay_id @sel, alloc/replay id @S1
131	        amo_req_t                       amo;
132	    } req_t;
133	
134	    typedef struct packed {            // S0-computed lookup delta (commit side)
135	        logic                          is_hit, is_dirty, mshr_pending;
136	        logic                          is_refill; // fill into an already-resident line (sector refill)
137	        logic [`CS_SECTORS_PER_LINE-1:0] evict_dirty_mask; // per-sector dirty of the evict way
138	        logic [`CS_TAG_SEL_BITS-1:0]   evict_tag;
139	        logic [MSHR_ADDR_WIDTH-1:0]    mshr_previd;
140	    } lookup_t;
141	
142	    typedef struct packed {            // data-array drive (S0 -> stD)
143	        req_t                          req;
144	        logic [`CS_WORD_WIDTH-1:0]     wdata;
145	        logic [NUM_WAYS-1:0]           tag_matches;
146	    } data_t;
147	
148	    typedef struct packed {            // response + memory request (S0 -> S1 -> stC)
149	        req_t                          req;
150	        lookup_t                       lk;
151	    } commit_t;
152	
153	    data_t   sel_req, st0, dat_in, stD;   // request + fill line: sel -> S0 -> stD
154	    commit_t cmt_in, st1, stC;            // request + lookup delta: S0 -> S1 -> stC
155	    lookup_t lk_st0;                      // S0 lookup results
156	
