218	    // ------------------------------------------------------------------------
219	    wire do_init_st0  = st0.req.valid && st0.req.is_init;
220	    wire do_flush_st0 = st0.req.valid && st0.req.is_flush;
221	    wire do_read_st0  = st0.req.valid && st0.req.is_creq && ~st0.req.rw;
222	    wire do_write_st0 = st0.req.valid && st0.req.is_creq && st0.req.rw;
223	    wire do_fill_st0  = st0.req.valid && st0.req.is_fill;
224	    wire do_lookup_st0 = do_read_st0 || do_write_st0;
225	
226	    wire do_read_st1  = st1.req.valid && st1.req.is_creq && ~st1.req.rw;
227	    wire do_write_st1 = st1.req.valid && st1.req.is_creq && st1.req.rw;
228	    wire do_lookup_st1 = do_read_st1 || do_write_st1;
229	
230	    wire do_read_stc  = stC.req.valid && stC.req.is_creq && ~stC.req.rw;
231	    wire do_write_stc = stC.req.valid && stC.req.is_creq && stC.req.rw;
232	
233	    wire do_init_std  = stD.req.valid && stD.req.is_init;
234	    wire do_fill_std  = stD.req.valid && stD.req.is_fill;
235	    wire do_flush_std = stD.req.valid && stD.req.is_flush;
236	    wire do_read_std  = stD.req.valid && stD.req.is_creq && ~stD.req.rw;
237	    wire do_write_std = stD.req.valid && stD.req.is_creq && stD.req.rw;
238	
239	    wire [`CS_LINE_SEL_BITS-1:0] line_idx_st0 = st0.req.addr[`CS_LINE_SEL_BITS-1:0];
240	    wire [`CS_TAG_SEL_BITS-1:0]  line_tag_st0 = `CS_LINE_ADDR_TAG(st0.req.addr);
241	    // Requested sector = top CS_SECTOR_SEL_BITS of the in-line word offset.
242	    wire [`UP(`CS_SECTOR_SEL_BITS)-1:0] sector_idx_st0;
243	    if (`CS_SECTOR_SEL_BITS != 0) begin : g_sector_idx
244	        assign sector_idx_st0 = st0.req.word_idx[`CS_WORD_SEL_BITS-1 -: `CS_SECTOR_SEL_BITS];
245	    end else begin : g_sector_idx0
