251	    // ------------------------------------------------------------------------
252	    // Bank-empty detection (gates flush). A request occupies S0, S1 and the
253	    // PIPE_EX commit-bubble stages (valid_st1 delayed 1..PIPE_EX); the parallel
254	    // data bubble S0->stD is subsumed by this window.
255	    // ------------------------------------------------------------------------
256	    wire pipe_inflight;
257	    if (PIPE_EX == 0) begin : g_no_bubble_occ
258	        assign pipe_inflight = st0.req.valid || st1.req.valid;
259	    end else begin : g_bubble_occ
260	        reg [PIPE_EX-1:0] commit_valid;
261	        always @(posedge clk) begin
262	            if (reset) begin
263	                commit_valid <= '0;
264	            end else if (~pipe_stall) begin
265	                commit_valid[0] <= st1.req.valid;
266	                for (int i = 1; i < PIPE_EX; ++i) begin
267	                    commit_valid[i] <= commit_valid[i-1];
268	                end
269	            end
270	        end
271	        assign pipe_inflight = st0.req.valid || st1.req.valid || (| commit_valid);
272	    end
273	    wire no_pending_req = ~pipe_inflight && mreq_queue_empty;
274	
275	    VX_cache_flush #(
276	        .BANK_ID    (BANK_ID),
277	        .CACHE_SIZE (CACHE_SIZE),
278	        .LINE_SIZE  (LINE_SIZE),
279	        .NUM_BANKS  (NUM_BANKS),
280	        .NUM_WAYS   (NUM_WAYS),
281	        .WRITEBACK  (WRITEBACK)
282	    ) cache_flush (
283	        .clk         (clk),
284	        .reset       (reset),
285	        .flush_begin (flush_begin),
286	        .flush_end   (flush_end),
287	        .flush_init  (init_valid),
288	        .flush_valid (flush_valid),
289	        .flush_line  (flush_sel),
290	        .flush_way   (flush_way),
291	        .flush_ready (flush_ready),
292	        .mshr_empty  (mshr_empty),
293	        .bank_empty  (no_pending_req)
294	    );
295	
296	    // wb_hold pauses the commit while a multi-beat per-sector writeback drains
297	    // (0 for single-sector lines, so the baseline pipe is unaffected).
298	    wire wb_hold;
299	    // amo_chain_stall paces a same-line AMO behind an in-flight commit by one
300	    // cycle; it is 0 for non-AMO traffic, so the baseline pipe is unaffected.
301	    wire pipe_stall = crsp_queue_stall || amo_chain_stall || wb_hold;
302	
303	    // ========================================================================
304	    // Input arbitration
305	    //   priority: init > replay > fill(mem_rsp) > flush > core-req
306	    // replay maximizes utilization (guaranteed hit); fill precedes flush/creq to
307	    // avoid deadlock on a miss; flush precedes creq for consistency.
308	    // ========================================================================
309	    // A chain head claimed by the forward port is masked from the arbiter
310	    // (it completes at the forward-response port instead of replaying); a
311	    // fill is held off while a forward drain is in progress so the staged
312	    // sector is not overwritten mid-chain.
313	    wire replay_mux    = replay_valid && ~fwd_head;
314	    wire fill_mux      = mem_rsp_valid && ~fwd_pending && ~fill_inflight;
315	
316	    wire replay_grant  = ~init_valid;
317	    wire replay_enable = replay_grant && replay_mux;
318	    wire fill_grant    = replay_grant && ~replay_enable;
319	    wire fill_enable   = fill_grant && fill_mux;
320	    wire flush_grant   = fill_grant && ~fill_enable;
321	    wire flush_enable  = flush_grant && flush_valid;
322	    wire creq_grant    = flush_grant && ~flush_enable;
323	
324	    // A core-request slot fires from a real core_req or a pending LLC AMO
325	    // writeback (synthetic write injected after a commit); mutually exclusive.
326	    // amo_commit_busy/req_input_defer enforce AMO ordering (0 for non-AMO banks).
327	    wire amo_creq_path = core_req_valid && ~amo_commit_busy && ~req_input_defer;
328	    wire amo_wb_path   = amo_wb_pending && ~amo_hit_st1;
329	    wire creq_enable   = creq_grant && (amo_creq_path || amo_wb_path);
330	
331	    assign replay_ready   = replay_grant && ~fwd_head && ~(!WRITEBACK && replay_rw && mreq_queue_alm_full) && ~pipe_stall;
332	    assign mem_rsp_ready  = fill_grant && ~fwd_pending && ~fill_inflight && ~(WRITEBACK && mreq_queue_alm_full) && ~pipe_stall;
333	    assign flush_ready    = flush_grant && ~(WRITEBACK && mreq_queue_alm_full) && ~pipe_stall;
334	    assign core_req_ready = creq_grant && ~mreq_queue_alm_full && ~mshr_alm_full && ~pipe_stall
335	                         && ~amo_commit_busy && ~req_input_defer;
336	
337	    wire init_fire    = init_valid;
338	    wire replay_fire  = replay_valid && replay_ready;
339	    wire mem_rsp_fire = mem_rsp_valid && mem_rsp_ready;
340	    wire flush_fire   = flush_valid && flush_ready;
341	    // amo_wb_path already excludes the cycle a fresh AMO commits at S1, so the
342	    // writeback never races the chain update.
343	    wire amo_wb_fire   = amo_wb_path && creq_grant && ~mreq_queue_alm_full && ~mshr_alm_full && ~pipe_stall;
344	    wire core_req_fire = (amo_creq_path || amo_wb_path) && creq_grant
345	                       && ~mreq_queue_alm_full && ~mshr_alm_full && ~pipe_stall;
346	
347	    wire [MSHR_ADDR_WIDTH-1:0] mem_rsp_id = mem_rsp_tag[MSHR_ADDR_WIDTH-1:0];
348	
349	    // A fill's sector lives only in the staging buffer until its data-array
350	    // write at stD, so with deferred stages (PIPE_EX>0) a back-to-back fill
351	    // must be held off while one is in flight. At PIPE_EX=0 the array write
352	    // samples the buffer on the same edge a new fill re-stages it (old value
353	    // read), so no interlock is needed.
354	    wire fill_inflight;
355	    if (PIPE_EX > 0) begin : g_fill_inflight
356	        reg [PIPE_EX-1:0] fill_busy;
357	        always @(posedge clk) begin
358	            if (reset) begin
359	                fill_busy <= '0;
360	            end else if (~pipe_stall) begin
361	                fill_busy <= PIPE_EX'({fill_busy, (mem_rsp_fire && ~is_passthru_fill_sel)});
362	            end
363	        end
364	        assign fill_inflight = (| fill_busy);
365	    end else begin : g_no_fill_inflight
366	        assign fill_inflight = 1'b0;
367	    end
