369	    // Fill word_idx: place the installed sector in the high (sector) bits of the
370	    // in-line word offset; low (word-in-sector) bits are don't-care for a fill.
371	    wire [WORD_SEL_WIDTH-1:0] fill_word_idx;
372	    if (`CS_SECTOR_SEL_BITS != 0) begin : g_fill_word_idx
373	        assign fill_word_idx = WORD_SEL_WIDTH'(mem_rsp_sector) << (`CS_WORD_SEL_BITS - `CS_SECTOR_SEL_BITS);
374	    end else begin : g_fill_word_idx0
375	        `UNUSED_VAR (mem_rsp_sector)
376	        assign fill_word_idx = '0;
377	    end
378	
379	    // generate-guarded width selects (the dead branch must not elaborate an
380	    // out-of-range slice when the other width path is taken).
381	    wire [TAG_WIDTH-1:0] mem_rsp_tag_s;
382	    if (TAG_WIDTH > MEM_TAG_WIDTH) begin : g_mem_rsp_tag_s_pad
383	        assign mem_rsp_tag_s = {mem_rsp_tag, (TAG_WIDTH-MEM_TAG_WIDTH)'(1'b0)};
384	    end else begin : g_mem_rsp_tag_s_cut
385	        assign mem_rsp_tag_s = mem_rsp_tag[MEM_TAG_WIDTH-1 -: TAG_WIDTH];
386	        `UNUSED_VAR (mem_rsp_tag)
387	    end
