389	    wire [TAG_WIDTH-1:0] flush_tag;
390	    if (UUID_WIDTH != 0) begin : g_flush_tag_uuid
391	        if (TAG_WIDTH > UUID_WIDTH) begin : g_pad
392	            assign flush_tag = {flush_uuid, (TAG_WIDTH-UUID_WIDTH)'(1'b0)};
393	        end else begin : g_cut
394	            assign flush_tag = flush_uuid[UUID_WIDTH-1 -: TAG_WIDTH];
395	        end
396	    end else begin : g_flush_tag_0
397	        `UNUSED_VAR (flush_uuid)
398	        assign flush_tag = '0;
399	    end
