401	    // Word payload mux (store / AMO-writeback data). Fill data does not ride
402	    // the pipeline: the staged fill buffer feeds the data array directly.
403	    wire [`CS_WORD_WIDTH-1:0] wdata_sel;
404	    if (WRITE_ENABLE) begin : g_wdata_sel
405	        assign wdata_sel = replay_mux ? replay_data
406	                         : (amo_wb_pending ? amo_wb_data : core_req_data);
407	    end else begin : g_wdata_sel_ro
408	        assign wdata_sel = '0;
409	        `UNUSED_VAR ({core_req_data, replay_data, amo_wb_data})
