412	    // Input mux -> arbitrated request (whole-struct populate). AMO priority
413	    // matches the mux (replay > wb > core_req): a replay can fire during a
414	    // pending wb (chained AMO replays from MSHR after a fill) and must not be
415	    // cleared by amo_wb_pending; the synthetic writeback carries amo.valid=0 so
416	    // it never re-commits at S1.
417	    always @(*) begin
418	        sel_req = '0;
419	        sel_req.req.valid    = init_fire || replay_fire || mem_rsp_fire || flush_fire || core_req_fire;
420	        sel_req.req.is_init  = init_valid;
421	        sel_req.req.is_fill  = fill_enable;
422	        sel_req.req.is_flush = flush_enable;
423	        sel_req.req.is_creq  = creq_enable || replay_enable;
424	        sel_req.req.is_replay = replay_enable;
425	        sel_req.req.is_passthru_fill = is_passthru_fill_sel;
426	        sel_req.req.rw       = replay_mux ? replay_rw : (amo_wb_pending ? 1'b1 : core_req_rw);
427	        sel_req.req.attr     = amo_wb_pending ? amo_wb_attr : (core_req_valid ? core_req_attr : '0);
428	        sel_req.req.way_idx  = flush_way;
429	        sel_req.req.addr     = (init_valid | flush_valid) ? `CS_LINE_ADDR_WIDTH'(flush_sel)
430	                             : (replay_mux ? replay_addr : (fill_mux ? mem_rsp_addr
431	                             : (amo_wb_pending ? amo_wb_addr : core_req_addr)));
432	        sel_req.req.byteen   = replay_mux ? replay_byteen : (amo_wb_pending ? amo_wb_byteen : core_req_byteen);
433	        // a fill carries the installed sector in its word_idx high bits so the
434	        // tag/data stages mark/write the right sector (0 when 1 sector/line).
435	        sel_req.req.word_idx = replay_mux ? replay_wsel
436	                             : (fill_mux ? fill_word_idx
437	                             : (amo_wb_pending ? amo_wb_word_idx : core_req_wsel));
438	        sel_req.req.req_idx  = replay_mux ? replay_idx : (amo_wb_pending ? amo_wb_idx : core_req_idx);
439	        sel_req.req.tag      = (init_valid | flush_valid) ? (flush_valid ? flush_tag : '0)
440	                             : (replay_mux ? replay_tag : (fill_mux ? mem_rsp_tag_s
441	                             : (amo_wb_pending ? amo_wb_tag : core_req_tag)));
442	        sel_req.req.mshr_id  = replay_id;
443	        sel_req.req.amo      = replay_mux ? replay_amo : (amo_wb_pending ? amo_req_t'('0)
444	                             : (core_req_valid ? core_req_amo : amo_req_t'('0)));
445	        sel_req.wdata        = wdata_sel;
446	        // tag_matches is computed at S0; left 0 here (overridden at the data bubble).
447	    end
448	
449	    // UUID extraction (debug + MSHR ordering): per stage, from the carried tag.
450	    wire [`UP(UUID_WIDTH)-1:0] req_uuid_sel, req_uuid_st0, req_uuid_st1, req_uuid_stc;
451	    if (UUID_WIDTH != 0) begin : g_req_uuid
452	        assign req_uuid_sel = sel_req.req.tag[TAG_WIDTH-1 -: UUID_WIDTH];
