454	        assign req_uuid_st1 = st1.req.tag[TAG_WIDTH-1 -: UUID_WIDTH];
455	        assign req_uuid_stc = stC.req.tag[TAG_WIDTH-1 -: UUID_WIDTH];
456	    end else begin : g_req_uuid_0
457	        assign {req_uuid_sel, req_uuid_st0, req_uuid_st1, req_uuid_stc} = '0;
458	    end
459	    `UNUSED_VAR ({req_uuid_st0, req_uuid_st1})
