463	        .DATAW  ($bits(data_t)),
464	        .RESETW (1)
465	    ) reg_s0 (
466	        .clk      (clk),
467	        .reset    (reset),
468	        .enable   (~pipe_stall),
469	        .data_in  (sel_req),
470	        .data_out (st0)
