473	    // ========================================================================
474	    // S0 lookup: replacement + tags + way-encode + MSHR allocate
475	    // ========================================================================
476	    wire [`CS_WAY_SEL_WIDTH-1:0] victim_way;
477	    wire [NUM_WAYS-1:0] tag_matches_st0;
478	    wire [NUM_WAYS-1:0] line_present_st0;
479	    wire [`CS_WAY_SEL_WIDTH-1:0] hit_idx_st0;
480	    wire evict_dirty_st0;
481	    wire [`CS_SECTORS_PER_LINE-1:0] evict_dirty_mask_st0;
482	    wire [`CS_TAG_SEL_BITS-1:0] evict_tag_st0;
