1267	        if (do_read_st1 && st1.lk.is_hit && ~pipe_stall) begin
1268	            `TRACE(3, ("%t: %s data-read: addr=0x%0h, way=%0d, line=%0d, wsel=%0d (#%0d)\n", $time, INSTANCE_ID,
1269	                full_addr_st1, st1.req.way_idx, st1.req.addr[`CS_LINE_SEL_BITS-1:0], st1.req.word_idx, req_uuid_st1))
1270	        end
1271	        if (do_write_st1 && st1.lk.is_hit && ~pipe_stall) begin
1272	            `TRACE(3, ("%t: %s data-write: addr=0x%0h, way=%0d, line=%0d, wsel=%0d, byteen=0x%h (#%0d)\n", $time, INSTANCE_ID,
1273	                full_addr_st1, st1.req.way_idx, st1.req.addr[`CS_LINE_SEL_BITS-1:0], st1.req.word_idx, st1.req.byteen, req_uuid_st1))
1274	        end
1275	        if (crsp_queue_fire) begin
1276	            `TRACE(2, ("%t: %s core-rd-rsp: addr=0x%0h, tag=0x%0h, req_idx=%0d, data=0x%h (#%0d)\n", $time, INSTANCE_ID,
1277	                addr_stc, stC.req.tag, stC.req.req_idx, crsp_queue_data, req_uuid_stc))
1278	        end
1279	        if (mreq_queue_push) begin
1280	            if (!WRITEBACK && do_write_stc) begin
1281	                `TRACE(2, ("%t: %s writethrough: addr=0x%0h, byteen=0x%h, data=0x%h (#%0d)\n", $time, INSTANCE_ID,
1282	                    mreq_queue_full_addr, mreq_queue_byteen, mreq_queue_data, req_uuid_stc))
1283	            end else if (WRITEBACK && do_writeback_stc) begin
1284	                `TRACE(2, ("%t: %s writeback: addr=0x%0h, byteen=0x%h, data=0x%h (#%0d)\n", $time, INSTANCE_ID,
1285	                    mreq_queue_full_addr, mreq_queue_byteen, mreq_queue_data, req_uuid_stc))
1286	            end else begin
1287	                `TRACE(2, ("%t: %s fill-req: addr=0x%0h, mshr_id=%0d (#%0d)\n", $time, INSTANCE_ID,
1288	                    mreq_queue_full_addr, stC.req.mshr_id, req_uuid_stc))
1289	            end
1290	        end
1291	    end
1292	`endif
1293	
1294	endmodule
